const NATIVE_MODEL_TRAINING_SERVICE_VERSION: &str = "zed.sim.native-model-training.v1";

#[derive(Clone)]
pub struct NativeRuntimeModelCompileService {
    identity: NativeNodeServiceIdentity,
    capabilities: Option<BackendCapabilityMatrix>,
}

