struct Task415MediaTextFixtureNode {
    backend: Arc<CpuBackend>,
}

#[cfg(feature = "test-support")]
impl NativeNode for Task415MediaTextFixtureNode {
    fn class_type(&self) -> &str {
        TASK415_MEDIA_TEXT_FIXTURE_CLASS
    }

    fn implementation_version(&self) -> &str {
        NATIVE_IMAGE_REGISTRY_VERSION
    }

    fn execute<'a>(
        &'a self,
        context: NodeContext,
        _inputs: BTreeMap<String, NativeValue>,
    ) -> BoxFuture<'a, Result<NodeOutcome, NodeFailure>> {
        Box::pin(async move {
            let renderer = NativeMediaTextRenderer::new()
                .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
            let background = [32_u8, 32, 32, 255].repeat(64 * 24);
            let runs = [TextRun {
                text: "01 café".to_owned(),
                x: 3,
                y: 2,
                font_size: 12,
                color: [240, 80, 40, 255],
            }];
            let tensor_context = native_image_tensor_context(&self.backend, &context);
            let image = renderer
                .render_over_rgba8(
                    64,
                    24,
                    &background,
                    &runs,
                    self.backend.as_ref(),
                    &tensor_context,
                )
                .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
            let pixels = image.as_f32_slice().map_err(tensor_failure)?;
            let mut hasher = Sha256::new();
            for (pixel_index, value) in pixels.iter().enumerate() {
                if pixel_index & 0xff == 0 {
                    tensor_context.check().map_err(tensor_failure)?;
                }
                hasher.update([(value * 255.0).round() as u8]);
            }
            let pixel_sha256 = format!("{:x}", hasher.finalize());
            tensor_context.check().map_err(tensor_failure)?;
            Ok(NodeOutcome::Values {
                outputs: vec![NativeValue::Primitive {
                    value: NativePrimitive::String(pixel_sha256.clone()),
                }],
                ui: Some(json!({
                    "task415_pixel_sha256": pixel_sha256,
                })),
                effects: Vec::new(),
            })
        })
    }
}

