#[cfg(feature = "test-support")]
struct Task404ModelTransformFixtureNode {
    backend: Arc<CpuBackend>,
}

#[cfg(feature = "test-support")]
impl NativeNode for Task404ModelTransformFixtureNode {
    fn class_type(&self) -> &str {
        TASK404_WORKER_FIXTURE_CLASS
    }

    fn implementation_version(&self) -> &str {
        NATIVE_IMAGE_REGISTRY_VERSION
    }

    fn execute<'a>(
        &'a self,
        context: NodeContext,
        inputs: BTreeMap<String, NativeValue>,
    ) -> BoxFuture<'a, Result<NodeOutcome, NodeFailure>> {
        Box::pin(async move {
            let tensor_context = native_image_tensor_context(&self.backend, &context);
            let variant = required_u64(&inputs, "variant")?;
            let model_handle = required_opaque_handle(&inputs, "model")?;
            let stored = context
                .handle_store()
                .resolve(
                    model_handle,
                    model_handle.handle_type(),
                    &context.cancellation,
                )
                .map_err(|error| runtime_failure(error.into()))?;
            let NativeStoredPayload::Model(model) = stored.as_ref() else {
                return Err(invalid_diffusion_input(
                    "Task404 worker fixture input stored a non-model payload",
                ));
            };
            let source = model.diffusion().ok_or_else(|| {
                invalid_diffusion_input("Task404 worker fixture requires a diffusion MODEL")
            })?;
            if source.role() != NativeModelResourceRole::Model {
                return Err(invalid_diffusion_input(
                    "Task404 worker fixture requires the MODEL role",
                ));
            }
            let recipe_digest = format!(
                "{:x}",
                Sha256::digest(
                    [
                        b"zed.sim.task404-worker-transform.v1".as_slice(),
                        &variant.to_le_bytes()
                    ]
                    .concat()
                )
            );
            let preexisting_selector = StateKeySelector::checked(
                vec![StateKeyMatch::Contains("init_x_linear.bias".to_owned())],
                Vec::new(),
            )
            .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
            let transform_selector = StateKeySelector::checked(
                vec![
                    StateKeyMatch::Suffix(".bias".to_owned()),
                    StateKeyMatch::Contains("init_x_linear".to_owned()),
                ],
                vec!["final".to_owned()],
            )
            .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
            let prepatched = source
                .scale_selected_state(&preexisting_selector, 1.0, &self.backend, &tensor_context)
                .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
            let scaled = prepatched
                .scale_selected_state(
                    &transform_selector,
                    1.0 + variant as f32,
                    &self.backend,
                    &tensor_context,
                )
                .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
            let hook_graph = Arc::new(
                ExecutionHookGraph::checked(
                    404,
                    vec![ExecutionHookOperation {
                        identifier: "task404.diffusion-wrapper".to_owned(),
                        order: 1,
                        kind: ExecutionHookKind::DiffusionWrapper,
                        scale: 1.0,
                        bias: variant as f32,
                        start_percent: 0.0,
                        end_percent: 1.0,
                        rng_address: 404,
                        rng_amplitude: 0.0,
                        hypernetwork: None,
                        context_window: None,
                        sampling_profile: None,
                    }],
                )
                .map_err(|error| invalid_diffusion_input(&error.to_string()))?,
            );
            let sampling_policy = Arc::new(
                NativeSamplingPolicy::checked(NativeSamplingPolicyKind::ContinuousV {
                    sigma_min: 0.03,
                    sigma_max: 14.0,
                    sigma_data: 1.0,
                })
                .map_err(|error| invalid_diffusion_input(&error.to_string()))?,
            );
            let guidance_modifiers = Arc::new(
                NativeGuidanceModifierChain::checked(vec![
                    NativeGuidanceModifier::AdaptiveProjectedGuidance {
                        eta: 0.5,
                        norm_threshold: 5.0,
                        momentum: 0.25,
                    },
                    NativeGuidanceModifier::CfgOverride { scale: 1.5 },
                ])
                .map_err(|error| invalid_diffusion_input(&error.to_string()))?,
            );
            let transformed = Arc::new(
                scaled
                    .with_hook_graph(hook_graph)
                    .and_then(|payload| payload.with_sampling_policy(sampling_policy))
                    .and_then(|payload| payload.with_guidance_modifiers(guidance_modifiers))
                    .map_err(|error| invalid_diffusion_input(&error.to_string()))?,
            );
            let selector_digest = transform_selector
                .identity()
                .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
            let evidence = PersistedNativeModelTransformEvidence::checked(
                context.node_id.clone(),
                source.digest_sha256(),
                recipe_digest,
                selector_digest.clone(),
                transformed.as_ref(),
            )
            .map_err(runtime_failure)?;
            let output_digest = evidence.output_digest.clone();
            let payload = NativeStoredModelPayload::native_diffusion(transformed)
                .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
            let handle = context
                .handle_store()
                .publish(
                    NativeStoredPayload::Model(Arc::new(payload)),
                    &context.cancellation,
                )
                .map_err(|error| runtime_failure(error.into()))?;
            Ok(NodeOutcome::Values {
                outputs: vec![NativeValue::Handle { value: handle }],
                ui: Some(json!({
                    crate::persistence::NATIVE_MODEL_TRANSFORM_EVIDENCE_UI_KEY: evidence,
                    "task404_output_digest": output_digest,
                    "task404_selector_identity": selector_digest,
                    "task404_patch_operation_count": evidence.patch_operation_count,
                    "task404_patch_graph_digest": evidence.patch_graph_digest,
                    "task404_conditioning_digest": evidence.conditioning_digest,
                })),
                effects: Vec::new(),
            })
        })
    }
}

