#[cfg(feature = "test-support")]
struct Task405TrainingDatasetFixtureNode {
    backend: Arc<CpuBackend>,
}

#[cfg(feature = "test-support")]
impl NativeNode for Task405TrainingDatasetFixtureNode {
    fn class_type(&self) -> &str {
        TASK405_DATASET_FIXTURE_CLASS
    }

    fn implementation_version(&self) -> &str {
        NATIVE_DIFFUSION_REGISTRY_VERSION
    }

    fn execute<'a>(
        &'a self,
        context: NodeContext,
        inputs: BTreeMap<String, NativeValue>,
    ) -> BoxFuture<'a, Result<NodeOutcome, NodeFailure>> {
        Box::pin(async move {
            let (model, _) = resolve_training_model(&context, training_first(&inputs, "model")?)?;
            let family = model
                .native_family_model_resource()
                .ok_or_else(|| invalid_diffusion_input("Task405 fixture requires family MODEL"))?;
            let tensor_context = native_image_tensor_context(&self.backend, &context);
            let latent_values = (0..36)
                .map(|index| (index as f32 - 18.0) * 0.025)
                .collect::<Vec<_>>();
            let latent = tensor_from_f32(
                &self.backend,
                &[1, 4, 3, 3],
                &latent_values,
                &tensor_context,
            )
            .map_err(classified_diffusion_failure)?;
            let conditioning_values = (0..4096)
                .map(|index| (index % 17) as f32 * 0.001 - 0.008)
                .collect::<Vec<_>>();
            let conditioning_tensor = tensor_from_f32(
                &self.backend,
                &[1, 2, 2_048],
                &conditioning_values,
                &tensor_context,
            )
            .map_err(classified_diffusion_failure)?;
            let latent = NativeLatentBundle::single(
                latent,
                None,
                None,
                NativeLatentMetadata::checked(None, None, Some(1), None)
                    .map_err(classified_diffusion_failure)?,
                &tensor_context,
            )
            .map_err(classified_diffusion_failure)?;
            let entry = ConditioningEntry::checked(
                "task405-positive",
                ConditioningValue::cross_attention(conditioning_tensor)
                    .map_err(classified_diffusion_failure)?,
                ConditioningEntryOptions::default(),
            )
            .map_err(classified_diffusion_failure)?;
            let conditioning = ConditioningSet::checked(
                family.conditioning_identity().clone(),
                vec![entry],
                &context.cancellation,
            )
            .map_err(classified_diffusion_failure)?;
            let latent_handle = context
                .handle_store()
                .publish(
                    NativeStoredPayload::Latent(Arc::new(latent)),
                    &context.cancellation,
                )
                .map_err(|error| runtime_failure(error.into()))?;
            let conditioning_handle = match context.handle_store().publish(
                NativeStoredPayload::Conditioning(Arc::new(conditioning)),
                &context.cancellation,
            ) {
                Ok(handle) => handle,
                Err(error) => {
                    rollback_native_handles(context.handle_store(), [&latent_handle])
                        .map_err(|rollback| runtime_failure(rollback.into()))?;
                    return Err(runtime_failure(error.into()));
                }
            };
            Ok(NodeOutcome::Values {
                outputs: vec![
                    NativeValue::Handle {
                        value: latent_handle,
                    },
                    NativeValue::Handle {
                        value: conditioning_handle,
                    },
                ],
                ui: None,
                effects: Vec::new(),
            })
        })
    }
}

