fn rollback_native_handles<'a>(
    store: &dyn crate::NativeHandleStore,
    handles: impl IntoIterator<Item = &'a NativeOpaqueHandle>,
) -> Result<(), NativeHandleStoreError> {
    let rollback_cancellation = CancellationToken::default();
    let mut first_error = None;
    for handle in handles {
        if let Err(error) = store.revoke(handle, &rollback_cancellation)
            && first_error.is_none()
        {
            first_error = Some(error);
        }
    }
    if let Some(error) = first_error {
        return Err(NativeHandleStoreError::Rejected(format!(
            "native conditioning/control rollback failed: {error}"
        )));
    }
    Ok(())
}

fn resolve_conditioning(
    context: &NodeContext,
    inputs: &BTreeMap<String, NativeValue>,
    name: &str,
) -> Result<ResolvedNative<Arc<ConditioningSet>>, NodeFailure> {
    let handle = required_opaque_handle(inputs, name)?;
    let expected_type = NativeHandleType::new(NativeHandleKind::Conditioning, "CONDITIONING")
        .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
    let stored = context
        .handle_store()
        .resolve(handle, &expected_type, &context.cancellation)
        .map_err(|error| runtime_failure(error.into()))?;
    let NativeStoredPayload::Conditioning(payload) = stored.as_ref() else {
        return Err(invalid_diffusion_input(
            "native CONDITIONING handle stored a non-conditioning payload",
        ));
    };
    payload
        .validate()
        .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
    Ok(ResolvedNative {
        value: payload.clone(),
        _resolved_payload: stored,
    })
}

fn resolve_optional_guider(
    context: &NodeContext,
    inputs: &BTreeMap<String, NativeValue>,
    name: &str,
) -> Result<Option<ResolvedNative<Arc<NativeGuiderPayload>>>, NodeFailure> {
    let Some(value) = inputs.get(name) else {
        return Ok(None);
    };
    let NativeValue::Handle { value: handle } = value else {
        return Err(invalid_diffusion_input(
            "native GUIDER input must be an opaque handle",
        ));
    };
    let expected_type = NativeHandleType::new(NativeHandleKind::StructuredCompute, "GUIDER")
        .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
    let stored = context
        .handle_store()
        .resolve(handle, &expected_type, &context.cancellation)
        .map_err(|error| runtime_failure(error.into()))?;
    let NativeStoredPayload::Guider(payload) = stored.as_ref() else {
        return Err(invalid_diffusion_input(
            "native GUIDER handle stored a non-guider payload",
        ));
    };
    payload
        .guider()
        .validate()
        .map_err(map_native_guider_runtime_error)
        .map_err(runtime_diffusion_failure)?;
    Ok(Some(ResolvedNative {
        value: payload.guider().clone(),
        _resolved_payload: stored,
    }))
}

fn resolve_optional_noise(
    context: &NodeContext,
    inputs: &BTreeMap<String, NativeValue>,
) -> Result<Option<ResolvedNative<Arc<NativeNoisePayload>>>, NodeFailure> {
    let Some(NativeValue::Handle { value: handle }) = inputs.get("noise") else {
        return if inputs.contains_key("noise") {
            Err(invalid_diffusion_input(
                "native NOISE input must be an opaque handle",
            ))
        } else {
            Ok(None)
        };
    };
    let expected = NativeHandleType::new(NativeHandleKind::StructuredCompute, "NOISE")
        .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
    let stored = context
        .handle_store()
        .resolve(handle, &expected, &context.cancellation)
        .map_err(|error| runtime_failure(error.into()))?;
    let NativeStoredPayload::Noise(payload) = stored.as_ref() else {
        return Err(invalid_diffusion_input(
            "native NOISE handle stored the wrong payload",
        ));
    };
    payload
        .validate()
        .map_err(map_native_guider_runtime_error)
        .map_err(runtime_diffusion_failure)?;
    Ok(Some(ResolvedNative {
        value: payload.clone(),
        _resolved_payload: stored,
    }))
}

fn resolve_optional_sampler(
    context: &NodeContext,
    inputs: &BTreeMap<String, NativeValue>,
) -> Result<Option<ResolvedNative<Arc<NativeSamplerPayload>>>, NodeFailure> {
    let Some(NativeValue::Handle { value: handle }) = inputs.get("sampler") else {
        return if inputs.contains_key("sampler") {
            Err(invalid_diffusion_input(
                "native SAMPLER input must be an opaque handle",
            ))
        } else {
            Ok(None)
        };
    };
    let expected = NativeHandleType::new(NativeHandleKind::StructuredCompute, "SAMPLER")
        .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
    let stored = context
        .handle_store()
        .resolve(handle, &expected, &context.cancellation)
        .map_err(|error| runtime_failure(error.into()))?;
    let NativeStoredPayload::Sampler(payload) = stored.as_ref() else {
        return Err(invalid_diffusion_input(
            "native SAMPLER handle stored the wrong payload",
        ));
    };
    payload
        .validate()
        .map_err(map_native_guider_runtime_error)
        .map_err(runtime_diffusion_failure)?;
    Ok(Some(ResolvedNative {
        value: payload.clone(),
        _resolved_payload: stored,
    }))
}

fn resolve_optional_sigmas(
    context: &NodeContext,
    inputs: &BTreeMap<String, NativeValue>,
) -> Result<Option<ResolvedNative<Arc<sim_tensor::NativeTensorPayload>>>, NodeFailure> {
    let Some(NativeValue::Handle { value: handle }) = inputs.get("sigmas") else {
        return if inputs.contains_key("sigmas") {
            Err(invalid_diffusion_input(
                "native SIGMAS input must be an opaque handle",
            ))
        } else {
            Ok(None)
        };
    };
    let expected = NativeHandleType::new(NativeHandleKind::Tensor, "SIGMAS")
        .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
    let stored = context
        .handle_store()
        .resolve(handle, &expected, &context.cancellation)
        .map_err(|error| runtime_failure(error.into()))?;
    let NativeStoredPayload::Tensor(payload) = stored.as_ref() else {
        return Err(invalid_diffusion_input(
            "native SIGMAS handle stored the wrong payload",
        ));
    };
    if payload.projection().role() != sim_tensor::NativeTensorRole::Sigmas {
        return Err(invalid_diffusion_input(
            "native SIGMAS payload has the wrong tensor role",
        ));
    }
    payload
        .validate()
        .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
    Ok(Some(ResolvedNative {
        value: payload.clone(),
        _resolved_payload: stored,
    }))
}

fn resolve_latent_bundle(
    context: &NodeContext,
    inputs: &BTreeMap<String, NativeValue>,
    name: &str,
) -> Result<ResolvedNative<Arc<NativeLatentBundle>>, NodeFailure> {
    let handle = required_opaque_handle(inputs, name)?;
    let expected_type = NativeHandleType::new(NativeHandleKind::Latent, "LATENT")
        .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
    let stored = context
        .handle_store()
        .resolve(handle, &expected_type, &context.cancellation)
        .map_err(|error| runtime_failure(error.into()))?;
    let NativeStoredPayload::Latent(payload) = stored.as_ref() else {
        return Err(invalid_diffusion_input(
            "native LATENT handle stored a non-latent payload",
        ));
    };
    payload
        .validate_retained()
        .map_err(classified_diffusion_failure)?;
    Ok(ResolvedNative {
        value: payload.clone(),
        _resolved_payload: stored,
    })
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
enum NativeDiffusionRole {
    Model,
    Clip,
    Vae,
}

struct NativeDiffusionState {
    provider: Arc<dyn NativeDiffusionProvider>,
    backend: Arc<CpuBackend>,
    admitted_identities: CanonicalNativeDiffusionCacheIdentities,
}

struct TrainLoraNode {
    implementation_version: String,
}

impl NativeNode for TrainLoraNode {
    fn class_type(&self) -> &str {
        "TrainLoraNode"
    }

    fn implementation_version(&self) -> &str {
        &self.implementation_version
    }

    fn cache_dependencies(
        &self,
        _context: &NodeContext,
        inputs: &BTreeMap<String, NativeValue>,
    ) -> Result<CacheDependencies, NodeFailure> {
        let seed = training_required_u64(inputs, "seed")?;
        Ok(CacheDependencies {
            rng_phase: Some(format!("native-model-training-seed:{seed}")),
            ..CacheDependencies::default()
        })
    }

    fn execute<'a>(
        &'a self,
        context: NodeContext,
        inputs: BTreeMap<String, NativeValue>,
    ) -> BoxFuture<'a, Result<NodeOutcome, NodeFailure>> {
        Box::pin(async move {
            let (model, sampling_policy) =
                resolve_training_model(&context, training_first(&inputs, "model")?)?;
            let rank = u32::try_from(training_required_u64(&inputs, "rank")?)
                .map_err(|_| invalid_diffusion_input("`rank` is outside u32"))?;
            let algorithm =
                parse_training_algorithm(training_required_string(&inputs, "algorithm")?)?;
            let lora_dtype = parse_lora_dtype(training_required_string(&inputs, "lora_dtype")?)?;
            let latents = training_values(&inputs, "latents")?
                .iter()
                .map(|value| resolve_training_latent(&context, value))
                .collect::<Result<Vec<_>, _>>()?;
            let positive = training_values(&inputs, "positive")?
                .iter()
                .map(|value| resolve_training_conditioning(&context, value))
                .collect::<Result<Vec<_>, _>>()?;
            let existing_lora = if inputs.contains_key("existing_lora_handle") {
                Some(resolve_training_lora(
                    &context,
                    training_first(&inputs, "existing_lora_handle")?,
                )?)
            } else {
                match training_first(&inputs, "existing_lora")? {
                    NativeValue::Primitive {
                        value: NativePrimitive::String(value),
                    } if value == "[None]" => None,
                    NativeValue::Primitive {
                        value: NativePrimitive::String(value),
                    } => Some(load_existing_training_lora(
                        &context, &model, value, rank, lora_dtype,
                    )?),
                    _ => {
                        return Err(invalid_diffusion_input(
                            "`existing_lora` must be a filename",
                        ));
                    }
                }
            };
            let request = NativeModelTrainingRequest::checked(
                model,
                latents,
                positive,
                existing_lora,
                training_required_u64(&inputs, "batch_size")?,
                training_required_u64(&inputs, "grad_accumulation_steps")?,
                training_required_u64(&inputs, "steps")?,
                training_required_f32(&inputs, "learning_rate")?,
                rank,
                parse_training_optimizer(training_required_string(&inputs, "optimizer")?)?,
                parse_training_loss(training_required_string(&inputs, "loss_function")?)?,
                training_required_u64(&inputs, "seed")?,
                parse_training_dtype(training_required_string(&inputs, "training_dtype")?)?,
                lora_dtype,
                training_required_bool(&inputs, "quantized_backward")?,
                algorithm,
                training_required_bool(&inputs, "gradient_checkpointing")?,
                u8::try_from(training_required_u64(&inputs, "checkpoint_depth")?)
                    .map_err(|_| invalid_diffusion_input("`checkpoint_depth` is outside u8"))?,
                training_required_bool(&inputs, "offloading")?,
                training_required_bool(&inputs, "bucket_mode")?,
                if training_required_bool(&inputs, "bypass_mode")? {
                    NativeLoraApplicationMode::Bypass
                } else {
                    NativeLoraApplicationMode::Normal
                },
            )
            .and_then(|request| request.with_sampling_policy(sampling_policy))
            .map_err(model_training_failure)?;
            let output = context
                .execute_native_model_training(&request)
                .map_err(model_training_failure)?;
            publish_model_training_output(&context, output)
        })
    }
}

fn load_existing_training_lora(
    context: &NodeContext,
    model: &NativeModelPayload,
    name: &str,
    rank: u32,
    dtype: DType,
) -> Result<Arc<NativeLoraModelResource>, NodeFailure> {
    let resolver = context
        .asset_resolver()
        .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
    let resolution = resolver
        .resolve_names(
            &NativeAssetNameResolutionRequest::checked(
                "loras",
                vec![name.to_owned()],
                "LORA_MODEL",
            )
            .map_err(|error| invalid_diffusion_input(&error.to_string()))?,
            &context.cancellation,
        )
        .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
    let asset = resolution
        .assets()
        .first()
        .filter(|asset| asset.name() == name)
        .ok_or_else(|| invalid_diffusion_input("existing LoRA resolution changed its name"))?;
    if resolution.assets().len() != 1 {
        return Err(invalid_diffusion_input(
            "existing LoRA resolution returned an unexpected cardinality",
        ));
    }
    let resolved = resolver
        .read_verified(
            &NativeAssetReadRequest::checked(
                asset.reference().clone(),
                MAX_NATIVE_TRAINING_LORA_BYTES,
            )
            .map_err(|error| invalid_diffusion_input(&error.to_string()))?,
            &context.cancellation,
        )
        .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
    let compute = context
        .compute_session()
        .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
    let tensor_context = compute
        .execution_context(context)
        .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
    let state = parse_existing_training_lora_state(
        resolved.bytes(),
        dtype,
        compute.backend(),
        &tensor_context,
    )?;
    let completed_steps = name
        .split("_steps_")
        .next()
        .and_then(|prefix| prefix.rsplit('_').next())
        .and_then(|steps| steps.parse::<u64>().ok())
        .ok_or_else(|| {
            invalid_diffusion_input(
                "existing LoRA filename must contain the source `_N_steps_` step marker",
            )
        })?;
    let detected_algorithm = native_training_state_algorithm(&state)
        .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
    NativeLoraModelResource::checked(
        model.identity().execution_sha256(),
        detected_algorithm,
        rank,
        dtype,
        completed_steps,
        state,
        &context.cancellation,
    )
    .map(Arc::new)
    .map_err(invalid_model_resource_failure)
}

fn parse_existing_training_lora_state(
    bytes: &[u8],
    dtype: DType,
    backend: &CpuBackend,
    context: &ExecutionContext<'_>,
) -> Result<BTreeMap<String, Tensor>, NodeFailure> {
    if bytes.len() < 8 || bytes.len() > MAX_NATIVE_TRAINING_LORA_BYTES as usize {
        return Err(invalid_diffusion_input(
            "existing LoRA safetensors size is invalid",
        ));
    }
    let header_length = u64::from_le_bytes(
        bytes[..8]
            .try_into()
            .map_err(|_| invalid_diffusion_input("existing LoRA header is truncated"))?,
    );
    let header_length = usize::try_from(header_length)
        .map_err(|_| invalid_diffusion_input("existing LoRA header size overflowed"))?;
    if header_length == 0 || header_length > MAX_NATIVE_TRAINING_LORA_HEADER_BYTES {
        return Err(invalid_diffusion_input(
            "existing LoRA header exceeds its bound",
        ));
    }
    let data_start = 8_usize
        .checked_add(header_length)
        .filter(|end| *end <= bytes.len())
        .ok_or_else(|| invalid_diffusion_input("existing LoRA header exceeds the asset"))?;
    let header: Value = serde_json::from_slice(&bytes[8..data_start])
        .map_err(|_| invalid_diffusion_input("existing LoRA header is invalid JSON"))?;
    let entries = header
        .as_object()
        .ok_or_else(|| invalid_diffusion_input("existing LoRA header must be an object"))?;
    if entries.is_empty() || entries.len() > 65_537 {
        return Err(invalid_diffusion_input(
            "existing LoRA tensor count is invalid",
        ));
    }
    let data = &bytes[data_start..];
    let mut state = BTreeMap::new();
    let mut ranges = Vec::new();
    for (name, value) in entries {
        context
            .check()
            .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
        if name == "__metadata__" {
            if !value.is_object() {
                return Err(invalid_diffusion_input("existing LoRA metadata is invalid"));
            }
            continue;
        }
        if name.is_empty() || name.len() > 64 * 1024 {
            return Err(invalid_diffusion_input(
                "existing LoRA tensor name is invalid",
            ));
        }
        let descriptor = value
            .as_object()
            .filter(|descriptor| {
                descriptor.len() == 3
                    && descriptor.contains_key("dtype")
                    && descriptor.contains_key("shape")
                    && descriptor.contains_key("data_offsets")
            })
            .ok_or_else(|| invalid_diffusion_input("existing LoRA tensor descriptor is invalid"))?;
        let source_dtype = descriptor
            .get("dtype")
            .and_then(Value::as_str)
            .filter(|dtype| matches!(*dtype, "F32" | "BF16"))
            .ok_or_else(|| invalid_diffusion_input("existing LoRA tensor dtype is unsupported"))?;
        let shape_values = descriptor
            .get("shape")
            .and_then(Value::as_array)
            .filter(|shape| shape.len() <= 8)
            .ok_or_else(|| invalid_diffusion_input("existing LoRA tensor shape is invalid"))?;
        let shape = shape_values
            .iter()
            .map(|dimension| {
                dimension
                    .as_u64()
                    .ok_or_else(|| invalid_diffusion_input("existing LoRA dimension is invalid"))
            })
            .collect::<Result<Vec<_>, _>>()?;
        let element_count = shape
            .iter()
            .try_fold(1_u64, |total, dimension| total.checked_mul(*dimension))
            .and_then(|count| usize::try_from(count).ok())
            .ok_or_else(|| invalid_diffusion_input("existing LoRA tensor shape overflowed"))?;
        let offsets = descriptor
            .get("data_offsets")
            .and_then(Value::as_array)
            .filter(|offsets| offsets.len() == 2)
            .ok_or_else(|| invalid_diffusion_input("existing LoRA tensor offsets are invalid"))?;
        let start = offsets[0]
            .as_u64()
            .and_then(|offset| usize::try_from(offset).ok())
            .ok_or_else(|| invalid_diffusion_input("existing LoRA tensor offset overflowed"))?;
        let end = offsets[1]
            .as_u64()
            .and_then(|offset| usize::try_from(offset).ok())
            .filter(|end| *end >= start && *end <= data.len())
            .ok_or_else(|| invalid_diffusion_input("existing LoRA tensor range is invalid"))?;
        let bytes_per_element = if source_dtype == "F32" { 4 } else { 2 };
        let expected_bytes = element_count
            .checked_mul(bytes_per_element)
            .ok_or_else(|| invalid_diffusion_input("existing LoRA tensor byte count overflowed"))?;
        if end - start != expected_bytes {
            return Err(invalid_diffusion_input(
                "existing LoRA tensor byte count differs",
            ));
        }
        ranges.push((start, end));
        let mut values = Vec::new();
        values
            .try_reserve_exact(element_count)
            .map_err(|_| resource_diffusion_failure("existing LoRA allocation failed"))?;
        for chunk in data[start..end].chunks_exact(bytes_per_element) {
            let value =
                if source_dtype == "F32" {
                    f32::from_le_bytes(chunk.try_into().map_err(|_| {
                        invalid_diffusion_input("existing LoRA F32 value is invalid")
                    })?)
                } else {
                    let bits = u16::from_le_bytes(chunk.try_into().map_err(|_| {
                        invalid_diffusion_input("existing LoRA BF16 value is invalid")
                    })?);
                    f32::from_bits(u32::from(bits) << 16)
                };
            if !value.is_finite() {
                return Err(invalid_diffusion_input(
                    "existing LoRA contains a non-finite value",
                ));
            }
            values.push(value);
        }
        let tensor = tensor_from_f32(backend, &shape, &values, context)
            .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
        let tensor = cast_to_with_context_exact_native(
            backend,
            &tensor,
            dtype,
            DeviceId::CPU,
            false,
            true,
            context,
        )
        .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
        if state.insert(name.clone(), tensor).is_some() {
            return Err(invalid_diffusion_input(
                "existing LoRA repeats a tensor name",
            ));
        }
    }
    ranges.sort_unstable();
    let mut expected_start = 0_usize;
    for (start, end) in ranges {
        if start != expected_start {
            return Err(invalid_diffusion_input(
                "existing LoRA tensor ranges overlap or have gaps",
            ));
        }
        expected_start = end;
    }
    if state.is_empty() || expected_start != data.len() {
        return Err(invalid_diffusion_input(
            "existing LoRA tensor payload is incomplete",
        ));
    }
    Ok(state)
}

struct LoraModelLoaderNode {
    implementation_version: String,
}

impl NativeNode for LoraModelLoaderNode {
    fn class_type(&self) -> &str {
        "LoraModelLoader"
    }

    fn implementation_version(&self) -> &str {
        &self.implementation_version
    }

    fn execute<'a>(
        &'a self,
        context: NodeContext,
        inputs: BTreeMap<String, NativeValue>,
    ) -> BoxFuture<'a, Result<NodeOutcome, NodeFailure>> {
        Box::pin(async move {
            let (model, _) = resolve_training_model(&context, training_first(&inputs, "model")?)?;
            let lora = resolve_training_lora(&context, training_first(&inputs, "lora")?)?;
            let strength = training_required_f32(&inputs, "strength_model")?;
            let bypass = training_required_bool_or(&inputs, "bypass", false)?;
            if strength == 0.0 {
                return Ok(NodeOutcome::Values {
                    outputs: vec![training_first(&inputs, "model")?.clone()],
                    ui: None,
                    effects: Vec::new(),
                });
            }
            let compute = context
                .compute_session()
                .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
            let tensor_context = compute
                .execution_context(&context)
                .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
            let transformed = Arc::new(
                model
                    .apply_trained_lora(
                        lora.as_ref(),
                        strength,
                        if bypass {
                            NativeLoraApplicationMode::Bypass
                        } else {
                            NativeLoraApplicationMode::Normal
                        },
                        compute.backend(),
                        &tensor_context,
                    )
                    .map_err(invalid_model_resource_failure)?,
            );
            let value = publish_native_model_resource(transformed, &context)?;
            Ok(NodeOutcome::Values {
                outputs: vec![value],
                ui: None,
                effects: Vec::new(),
            })
        })
    }
}

fn publish_model_training_output(
    context: &NodeContext,
    output: NativeModelTrainingOutput,
) -> Result<NodeOutcome, NodeFailure> {
    let evidence = PersistedNativeModelTrainingEvidence::checked(context.node_id.clone(), &output)
        .map_err(runtime_failure)?;
    let lora_payload = Arc::new(
        NativeModelPayload::lora_model(output.lora().clone())
            .map_err(invalid_model_resource_failure)?,
    );
    let admitted = admit_native_model_resource(lora_payload)?;
    let lora_handle = publish_admitted_native_model_resource(admitted, context)?;
    let loss_handle = match context.handle_store().publish(
        NativeStoredPayload::LossMap(output.losses().clone()),
        &context.cancellation,
    ) {
        Ok(handle) => handle,
        Err(error) => {
            rollback_native_handles(context.handle_store(), [&lora_handle])
                .map_err(|rollback| runtime_failure(rollback.into()))?;
            return Err(runtime_failure(error.into()));
        }
    };
    if let Err(error) = context.cancellation.check() {
        rollback_native_handles(context.handle_store(), [&loss_handle, &lora_handle])
            .map_err(|rollback| runtime_failure(rollback.into()))?;
        return Err(cancelled_diffusion_failure(error.to_string()));
    }
    Ok(NodeOutcome::Values {
        outputs: vec![
            NativeValue::Handle { value: lora_handle },
            NativeValue::Handle { value: loss_handle },
            NativeValue::Primitive {
                value: NativePrimitive::UnsignedInteger(output.steps()),
            },
        ],
        ui: Some(json!({
            crate::persistence::NATIVE_MODEL_TRAINING_EVIDENCE_UI_KEY: evidence,
        })),
        effects: Vec::new(),
    })
}

fn training_values<'a>(
    inputs: &'a BTreeMap<String, NativeValue>,
    name: &str,
) -> Result<&'a [NativeValue], NodeFailure> {
    match inputs.get(name) {
        Some(NativeValue::List { values }) if !values.is_empty() => Ok(values),
        Some(value) => Ok(std::slice::from_ref(value)),
        None => Err(invalid_diffusion_input(&format!("`{name}` is required"))),
    }
}

fn training_first<'a>(
    inputs: &'a BTreeMap<String, NativeValue>,
    name: &str,
) -> Result<&'a NativeValue, NodeFailure> {
    training_values(inputs, name)?
        .first()
        .ok_or_else(|| invalid_diffusion_input(&format!("`{name}` is empty")))
}

fn training_required_string<'a>(
    inputs: &'a BTreeMap<String, NativeValue>,
    name: &str,
) -> Result<&'a str, NodeFailure> {
    source_scalar_string(training_first(inputs, name)?)
        .ok_or_else(|| invalid_diffusion_input(&format!("`{name}` must be a string")))
}

fn training_required_u64(
    inputs: &BTreeMap<String, NativeValue>,
    name: &str,
) -> Result<u64, NodeFailure> {
    match training_first(inputs, name)? {
        NativeValue::Primitive {
            value: NativePrimitive::UnsignedInteger(value),
        } => Ok(*value),
        NativeValue::Primitive {
            value: NativePrimitive::Integer(value),
        } => u64::try_from(*value)
            .map_err(|_| invalid_diffusion_input(&format!("`{name}` must be non-negative"))),
        _ => Err(invalid_diffusion_input(&format!(
            "`{name}` must be an integer"
        ))),
    }
}

fn training_required_f32(
    inputs: &BTreeMap<String, NativeValue>,
    name: &str,
) -> Result<f32, NodeFailure> {
    let value = match training_first(inputs, name)? {
        NativeValue::Primitive {
            value: NativePrimitive::Number(value),
        } => *value as f32,
        NativeValue::Primitive {
            value: NativePrimitive::Integer(value),
        } => *value as f32,
        NativeValue::Primitive {
            value: NativePrimitive::UnsignedInteger(value),
        } => *value as f32,
        _ => {
            return Err(invalid_diffusion_input(&format!(
                "`{name}` must be a number"
            )));
        }
    };
    value
        .is_finite()
        .then_some(value)
        .ok_or_else(|| invalid_diffusion_input(&format!("`{name}` must be finite")))
}

fn training_required_bool(
    inputs: &BTreeMap<String, NativeValue>,
    name: &str,
) -> Result<bool, NodeFailure> {
    training_required_bool_or(inputs, name, false)
}

fn training_required_bool_or(
    inputs: &BTreeMap<String, NativeValue>,
    name: &str,
    default: bool,
) -> Result<bool, NodeFailure> {
    let Some(_) = inputs.get(name) else {
        return Ok(default);
    };
    match training_first(inputs, name)? {
        NativeValue::Primitive {
            value: NativePrimitive::Boolean(value),
        } => Ok(*value),
        _ => Err(invalid_diffusion_input(&format!(
            "`{name}` must be a boolean"
        ))),
    }
}

fn resolve_training_model(
    context: &NodeContext,
    value: &NativeValue,
) -> Result<(Arc<NativeModelPayload>, Arc<NativeSamplingPolicy>), NodeFailure> {
    let NativeValue::Handle { value: handle } = value else {
        return Err(invalid_diffusion_input(
            "training model must be a MODEL handle",
        ));
    };
    let stored = context
        .handle_store()
        .resolve(handle, handle.handle_type(), &context.cancellation)
        .map_err(|error| runtime_failure(error.into()))?;
    let NativeStoredPayload::Model(model) = stored.as_ref() else {
        return Err(invalid_diffusion_input(
            "training model handle has wrong payload",
        ));
    };
    let payload = model.model_payload().clone();
    if payload.native_family_model_resource().is_none() {
        return Err(invalid_diffusion_input(
            "training requires a retained native family MODEL",
        ));
    }
    let sampling_policy = match model.diffusion() {
        Some(diffusion) => diffusion.sampling_policy().clone(),
        None => Arc::new(
            sim_sampler::profile_for_model(&payload)
                .map_err(|error| invalid_diffusion_input(&error.to_string()))?,
        ),
    };
    Ok((payload, sampling_policy))
}

fn resolve_training_lora(
    context: &NodeContext,
    value: &NativeValue,
) -> Result<Arc<NativeLoraModelResource>, NodeFailure> {
    let NativeValue::Handle { value: handle } = value else {
        return Err(invalid_diffusion_input(
            "LoRA input must be a LORA_MODEL handle",
        ));
    };
    let expected = NativeHandleType::new(NativeHandleKind::Model, "LORA_MODEL")
        .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
    let stored = context
        .handle_store()
        .resolve(handle, &expected, &context.cancellation)
        .map_err(|error| runtime_failure(error.into()))?;
    let NativeStoredPayload::Model(model) = stored.as_ref() else {
        return Err(invalid_diffusion_input("LoRA handle has wrong payload"));
    };
    model
        .model_payload()
        .lora_model_resource()
        .cloned()
        .ok_or_else(|| invalid_diffusion_input("LORA_MODEL handle has no retained LoRA resource"))
}

