fn parse_training_optimizer(value: &str) -> Result<NativeTrainingOptimizer, NodeFailure> {
    match value {
        "AdamW" => Ok(NativeTrainingOptimizer::AdamW),
        "Adam" => Ok(NativeTrainingOptimizer::Adam),
        "SGD" => Ok(NativeTrainingOptimizer::Sgd),
        "RMSprop" => Ok(NativeTrainingOptimizer::Rmsprop),
        _ => Err(invalid_diffusion_input("unsupported training optimizer")),
    }
}

fn parse_training_loss(value: &str) -> Result<NativeTrainingLoss, NodeFailure> {
    match value {
        "MSE" => Ok(NativeTrainingLoss::Mse),
        "L1" => Ok(NativeTrainingLoss::L1),
        "Huber" => Ok(NativeTrainingLoss::Huber),
        "SmoothL1" => Ok(NativeTrainingLoss::SmoothL1),
        _ => Err(invalid_diffusion_input("unsupported training loss")),
    }
}

fn parse_training_dtype(value: &str) -> Result<NativeTrainingComputeDType, NodeFailure> {
    match value {
        "bf16" => Ok(NativeTrainingComputeDType::Bf16),
        "fp32" => Ok(NativeTrainingComputeDType::F32),
        "none" => Ok(NativeTrainingComputeDType::Preserve),
        _ => Err(invalid_diffusion_input("unsupported training dtype")),
    }
}

fn parse_lora_dtype(value: &str) -> Result<DType, NodeFailure> {
    match value {
        "bf16" => Ok(DType::Bf16),
        "fp32" => Ok(DType::F32),
        _ => Err(invalid_diffusion_input("unsupported LoRA dtype")),
    }
}

fn parse_training_algorithm(value: &str) -> Result<NativeModelTrainingAlgorithm, NodeFailure> {
    match value {
        "LoRA" => Ok(NativeModelTrainingAlgorithm::LoRa),
        "LoHa" => Ok(NativeModelTrainingAlgorithm::LoHa),
        "LoKr" => Ok(NativeModelTrainingAlgorithm::LoKr),
        "OFT" => Ok(NativeModelTrainingAlgorithm::Oft),
        _ => Err(invalid_diffusion_input(
            "unsupported weight-adapter algorithm",
        )),
    }
}

fn model_training_failure(error: NativeModelTrainingServiceError) -> NodeFailure {
    match error {
        NativeModelTrainingServiceError::Cancelled => {
            cancelled_diffusion_failure(error.to_string())
        }
        NativeModelTrainingServiceError::OutOfMemory => {
            resource_diffusion_failure(error.to_string())
        }
        error => diffusion_failure(error),
    }
}

fn native_diffusion_handle_type(
    role: NativeDiffusionRole,
) -> Result<NativeHandleType, NativeImageRuntimeError> {
    let (kind, type_id) = match role {
        NativeDiffusionRole::Model => (NativeHandleKind::Model, "MODEL"),
        NativeDiffusionRole::Clip => (NativeHandleKind::Clip, "CLIP"),
        NativeDiffusionRole::Vae => (NativeHandleKind::Vae, "VAE"),
    };
    Ok(NativeHandleType::new(kind, type_id)?)
}

fn portable_diffusion_payload(
    bundle: &NativeDiffusionBundle,
    role: NativeDiffusionRole,
) -> Result<NativeDiffusionPayload, NativeImageRuntimeError> {
    let payload = match role {
        NativeDiffusionRole::Model => {
            let model = Arc::new(
                NativeModelPayload::sd15_model(bundle.model.clone())
                    .map_err(|error| NativeImageRuntimeError::Handle(error.to_string()))?,
            );
            let control = bundle
                .conditioning
                .control
                .as_ref()
                .map(|control| {
                    if let Some(vae) = &control.vae {
                        PortableControlExecution::checked_with_vae(
                            control.chain.clone(),
                            control.executor.clone(),
                            vae.clone(),
                        )
                    } else {
                        PortableControlExecution::checked(
                            control.chain.clone(),
                            control.executor.clone(),
                        )
                    }
                })
                .transpose()
                .map_err(|error| NativeImageRuntimeError::Handle(error.to_string()))?;
            let conditioning = Arc::new(
                PortableConditioningPayload::checked_sd15(
                    bundle.model_digest(),
                    bundle.model.as_ref(),
                    bundle.conditioning.patch_graph.clone(),
                    control,
                )
                .map_err(|error| NativeImageRuntimeError::Handle(error.to_string()))?,
            );
            NativeDiffusionPayload::model(model, conditioning)
        }
        NativeDiffusionRole::Clip => NativeDiffusionPayload::clip(Arc::new(
            NativeModelPayload::sd1_clip(bundle.tokenizer.clone(), bundle.clip.clone())
                .map_err(|error| NativeImageRuntimeError::Handle(error.to_string()))?,
        )),
        NativeDiffusionRole::Vae => NativeDiffusionPayload::vae(Arc::new(
            NativeModelPayload::native_vae(bundle.vae.clone())
                .map_err(|error| NativeImageRuntimeError::Handle(error.to_string()))?,
        )),
    };
    payload.map_err(|error| NativeImageRuntimeError::Handle(error.to_string()))
}

fn publish_diffusion_bundle(
    bundle: &NativeDiffusionBundle,
    context: &NodeContext,
    role: NativeDiffusionRole,
) -> Result<NativeValue, NodeFailure> {
    let payload = portable_diffusion_payload(bundle, role).map_err(runtime_failure)?;
    let payload = NativeStoredModelPayload::native_diffusion(Arc::new(payload))
        .map_err(|error| invalid_diffusion_input(&error.to_string()))?;
    let handle = context
        .handle_store()
        .publish(
            NativeStoredPayload::Model(Arc::new(payload)),
            &context.cancellation,
        )
        .map_err(|error| runtime_failure(error.into()))?;
    Ok(NativeValue::Handle { value: handle })
}

pub fn publish_native_model_resource(
    resource: Arc<NativeModelPayload>,
    context: &NodeContext,
) -> Result<NativeValue, NodeFailure> {
    let payload = admit_native_model_resource(resource)?;
    let handle = publish_admitted_native_model_resource(payload, context)?;
    Ok(NativeValue::Handle { value: handle })
}

fn publish_admitted_native_model_resource(
    payload: NativeStoredModelPayload,
    context: &NodeContext,
) -> Result<NativeOpaqueHandle, NodeFailure> {
    context
        .handle_store()
        .publish(
            NativeStoredPayload::Model(Arc::new(payload)),
            &context.cancellation,
        )
        .map_err(|error| match error {
            NativeHandleStoreError::Cancelled => NodeFailure {
                code: "native_model_resource_cancelled".to_owned(),
                message: error.to_string(),
                kind: NodeFailureKind::Interrupted,
                retryable: false,
            },
            error => NodeFailure {
                code: "native_model_resource_publication_failed".to_owned(),
                message: error.to_string(),
                kind: NodeFailureKind::Failure,
                retryable: false,
            },
        })
}

fn admit_native_model_resource(
    resource: Arc<NativeModelPayload>,
) -> Result<NativeStoredModelPayload, NodeFailure> {
    resource
        .validate()
        .map_err(invalid_model_resource_failure)?;
    let diffusion = match resource.identity().role() {
        sim_model::NativeModelResourceRole::Model => {
            if let Some(family) = resource.native_family_model_resource() {
                let conditioning = PortableConditioningPayload::checked_family(
                    resource.as_ref(),
                    family.patch_graph().clone(),
                    None,
                )
                .map_err(invalid_model_resource_failure)?;
                Some(
                    NativeDiffusionPayload::model(resource.clone(), Arc::new(conditioning))
                        .map_err(invalid_model_resource_failure)?,
                )
            } else if let Some(model) = resource.model() {
                let Some(model) = model.sd15() else {
                    return NativeStoredModelPayload::model_resource(resource)
                        .map_err(invalid_model_resource_failure);
                };
                let patch_graph = Arc::new(
                    PatchGraph::checked_semantic(
                        resource.identity().artifact_sha256().to_owned(),
                        Vec::new(),
                    )
                    .map_err(invalid_model_resource_failure)?,
                );
                let conditioning = PortableConditioningPayload::checked_sd15(
                    resource.identity().artifact_sha256(),
                    model,
                    patch_graph,
                    None,
                )
                .map_err(invalid_model_resource_failure)?;
                Some(
                    NativeDiffusionPayload::model(resource.clone(), Arc::new(conditioning))
                        .map_err(invalid_model_resource_failure)?,
                )
            } else {
                None
            }
        }
        sim_model::NativeModelResourceRole::Clip if resource.clip().is_some() => Some(
            NativeDiffusionPayload::clip(resource.clone())
                .map_err(invalid_model_resource_failure)?,
        ),
        sim_model::NativeModelResourceRole::Vae
            if resource.vae().is_some() || resource.structured_vae().is_some() =>
        {
            Some(
                NativeDiffusionPayload::vae(resource.clone())
                    .map_err(invalid_model_resource_failure)?,
            )
        }
        sim_model::NativeModelResourceRole::Clip => None,
        sim_model::NativeModelResourceRole::Vae => {
            return Err(invalid_model_resource_failure(
                "model resource has no canonical diffusion backing",
            ));
        }
        sim_model::NativeModelResourceRole::AudioEncoder
        | sim_model::NativeModelResourceRole::BackgroundRemoval
        | sim_model::NativeModelResourceRole::ClipVision
        | sim_model::NativeModelResourceRole::Da3Model
        | sim_model::NativeModelResourceRole::FrameInterpolation
        | sim_model::NativeModelResourceRole::Gligen
        | sim_model::NativeModelResourceRole::LatentUpscaleModel
        | sim_model::NativeModelResourceRole::MogeModel
        | sim_model::NativeModelResourceRole::OpticalFlow
        | sim_model::NativeModelResourceRole::Photomaker
        | sim_model::NativeModelResourceRole::StyleModel => None,
        sim_model::NativeModelResourceRole::LoraModel => None,
        sim_model::NativeModelResourceRole::ControlNet
        | sim_model::NativeModelResourceRole::FaceDetection
        | sim_model::NativeModelResourceRole::Hooks
        | sim_model::NativeModelResourceRole::HookKeyframes
        | sim_model::NativeModelResourceRole::LatentOperation
        | sim_model::NativeModelResourceRole::ModelPatch
        | sim_model::NativeModelResourceRole::UpscaleModel => {
            return Err(model_resource_service_failure(
                NativeModelResourceServiceError::Unavailable,
            ));
        }
    };
    if let Some(diffusion) = diffusion {
        NativeStoredModelPayload::native_diffusion(Arc::new(diffusion))
            .map_err(invalid_model_resource_failure)
    } else {
        NativeStoredModelPayload::model_resource(resource).map_err(invalid_model_resource_failure)
    }
}

fn invalid_model_resource_failure(error: impl ToString) -> NodeFailure {
    NodeFailure {
        code: "invalid_native_model_resource".to_owned(),
        message: error.to_string(),
        kind: NodeFailureKind::Failure,
        retryable: false,
    }
}

fn model_resource_service_failure(error: NativeModelResourceServiceError) -> NodeFailure {
    let (code, kind, retryable) = match error {
        NativeModelResourceServiceError::Cancelled => (
            "native_model_resource_cancelled",
            NodeFailureKind::Interrupted,
            false,
        ),
        NativeModelResourceServiceError::SourceUnavailable
        | NativeModelResourceServiceError::StaleIdentity => (
            "native_model_resource_service_unavailable",
            NodeFailureKind::Failure,
            true,
        ),
        NativeModelResourceServiceError::Unavailable => (
            "native_model_resource_unavailable",
            NodeFailureKind::Failure,
            false,
        ),
        _ => (
            "native_model_resource_invalid",
            NodeFailureKind::Failure,
            false,
        ),
    };
    NodeFailure {
        code: code.to_owned(),
        message: error.to_string(),
        kind,
        retryable,
    }
}

pub fn load_and_publish_native_model_resource(
    request: &NativeModelResourceRequest,
    context: &NodeContext,
) -> Result<
    (
        NativeValue,
        crate::persistence::PersistedNativeModelResourceEvidence,
    ),
    NodeFailure,
> {
    let (mut outputs, mut evidence) =
        load_and_publish_native_model_resources(std::slice::from_ref(request), context)?;
    let output = outputs.pop().ok_or_else(|| {
        invalid_model_resource_failure("model-resource transaction returned no output")
    })?;
    let evidence = evidence.pop().ok_or_else(|| {
        invalid_model_resource_failure("model-resource transaction returned no evidence")
    })?;
    Ok((output, evidence))
}

fn load_and_publish_native_model_resources(
    requests: &[NativeModelResourceRequest],
    context: &NodeContext,
) -> Result<
    (
        Vec<NativeValue>,
        Vec<crate::persistence::PersistedNativeModelResourceEvidence>,
    ),
    NodeFailure,
> {
    let mut staged = Vec::with_capacity(requests.len());
    for request in requests {
        request
            .validate_recipe()
            .map_err(model_resource_service_failure)?;
        let preflight = context
            .preflight_native_model_resource(request)
            .map_err(model_resource_service_failure)?;
        let resource = context
            .load_native_model_resource(request)
            .map_err(model_resource_service_failure)?;
        let evidence = crate::persistence::PersistedNativeModelResourceEvidence::checked(
            context.node_id.clone(),
            preflight,
            resource.identity().clone(),
        )
        .map_err(invalid_model_resource_failure)?;
        let payload = admit_native_model_resource(resource)?;
        staged.push((payload, evidence));
    }
    let mut outputs = Vec::with_capacity(staged.len());
    let mut evidence = Vec::with_capacity(staged.len());
    let mut published = Vec::with_capacity(staged.len());
    for (payload, persisted) in staged {
        let handle = match publish_admitted_native_model_resource(payload, context) {
            Ok(handle) => handle,
            Err(error) => {
                let rollback_cancellation = CancellationToken::default();
                for handle in published.drain(..).rev() {
                    if let Err(rollback_error) = context
                        .handle_store()
                        .revoke(&handle, &rollback_cancellation)
                    {
                        return Err(NodeFailure {
                            code: "native_model_resource_rollback_failed".to_owned(),
                            message: format!(
                                "{error}; model-resource publication rollback failed: {rollback_error}"
                            ),
                            kind: NodeFailureKind::Failure,
                            retryable: false,
                        });
                    }
                }
                return Err(error);
            }
        };
        outputs.push(NativeValue::Handle {
            value: handle.clone(),
        });
        published.push(handle);
        evidence.push(persisted);
    }
    Ok((outputs, evidence))
}

#[derive(Clone, Copy)]
struct NativeModelResourceLoaderRecipe {
    role: sim_model::NativeModelResourceRole,
    folder_category: &'static str,
    source_inputs: &'static [&'static str],
}

struct NativeModelResourceLoaderNode {
    class_type: String,
    implementation_version: String,
    recipes: &'static [NativeModelResourceLoaderRecipe],
}

impl NativeModelResourceLoaderNode {
    fn requests(
        &self,
        inputs: &BTreeMap<String, NativeValue>,
    ) -> Result<Vec<NativeModelResourceRequest>, NodeFailure> {
        self.recipes
            .iter()
            .map(|recipe| {
                let source_names = recipe
                    .source_inputs
                    .iter()
                    .map(|name| required_source_string(inputs, name).map(ToOwned::to_owned))
                    .collect::<Result<Vec<_>, _>>()?;
                NativeModelResourceRequest::checked(
                    recipe.role,
                    recipe.folder_category,
                    source_names,
                )
                .map_err(model_resource_service_failure)
            })
            .collect()
    }
}

impl NativeNode for NativeModelResourceLoaderNode {
    fn class_type(&self) -> &str {
        &self.class_type
    }

    fn implementation_version(&self) -> &str {
        &self.implementation_version
    }

    fn cache_dependencies(
        &self,
        context: &NodeContext,
        inputs: &BTreeMap<String, NativeValue>,
    ) -> Result<CacheDependencies, NodeFailure> {
        let mut artifact_digests = BTreeMap::new();
        for (recipe_ordinal, request) in self.requests(inputs)?.iter().enumerate() {
            let preflight = context
                .preflight_native_model_resource(request)
                .map_err(model_resource_service_failure)?;
            artifact_digests.insert(
                format!("model_resource.{recipe_ordinal}.selection"),
                preflight.ordered_source_identity_sha256().to_owned(),
            );
            artifact_digests.insert(
                format!("model_resource.{recipe_ordinal}.manifest"),
                preflight.manifest_sha256().to_owned(),
            );
            for (source_ordinal, digest) in
                preflight.ordered_model_identity_sha256().iter().enumerate()
            {
                artifact_digests.insert(
                    format!("model_resource.{recipe_ordinal}.source.{source_ordinal}"),
                    digest.clone(),
                );
            }
        }
        Ok(CacheDependencies {
            artifact_digests,
            ..CacheDependencies::default()
        })
    }

    fn execute<'a>(
        &'a self,
        context: NodeContext,
        inputs: BTreeMap<String, NativeValue>,
    ) -> BoxFuture<'a, Result<NodeOutcome, NodeFailure>> {
        Box::pin(async move {
            let requests = self.requests(&inputs)?;
            let (outputs, evidence) = load_and_publish_native_model_resources(&requests, &context)?;
            Ok(NodeOutcome::Values {
                outputs,
                ui: Some(json!({"native_model_resource_evidence": evidence})),
                effects: Vec::new(),
            })
        })
    }
}

