    pub fn with_model_source_worker(
        mut self,
        binding: NativeModelSourceWorkerBinding,
    ) -> Result<(Self, crate::NativeModelSourceTransportHost), NativeImageRuntimeError> {
        binding.validate()?;
        #[cfg(feature = "test-support")]
        {
            self.previous_handle_store_identity_for_test =
                binding.previous_handle_store_identity_for_test();
        }
        if let Some(identity) = binding.handle_store_identity() {
            let mut generation = self.handle_store_generation.lock();
            if generation.identity() != identity {
                *generation = crate::NativeHandleStoreGeneration::from_identity(identity)?;
            }
        }
        let (transport, host) = crate::NativeModelSourceTransport::channel();
        self.model_source_transport = Some((binding, transport));
        Ok((self, host))
    }

