#[cfg(feature = "test-support")]
#[doc(hidden)]
pub fn exercise_conditioning_control_retry_after_worker_replacement_for_test(
    config: NativeExecutionControllerConfig,
    event_bus: ExecutionEventBus,
    replacement_plan: Option<CompiledPlan>,
) -> Result<NativeConditioningControlWorkerReplacementEvidence, NativeImageRuntimeError> {
    smol::block_on(async move {
        config.validate()?;
        let roots = config.roots()?;
        let supervisor = RuntimeSupervisor::start(config.worker.clone())
            .await
            .map_err(|error| NativeImageRuntimeError::Execution(error.to_string()))?;
        let original_process_id = supervisor.worker_process_id().ok_or_else(|| {
            NativeImageRuntimeError::Execution(
                "original native worker has no process ID".to_owned(),
            )
        })?;
        let output_committer = config.output_committer.clone();
        let input_authorization = authorize_native_input_reader(&roots.profile_id)
            .map_err(|error| NativeImageRuntimeError::Asset(error.to_string()))?;
        let output_authorization = authorize_native_output_committer(&roots.profile_id)
            .map_err(|error| NativeImageRuntimeError::Asset(error.to_string()))?;
        let model_source_policy = PermissionPolicy::native_runtime_services(&roots.profile_id)
            .map_err(|error| NativeImageRuntimeError::Asset(error.to_string()))?;
        let model_source_authorization = authorize_native_api_asset_reader(&model_source_policy)
            .map_err(|error| NativeImageRuntimeError::Asset(error.to_string()))?;
        let model_source_registry =
            NativeAssetResolverRegistry::new(config.assets.clone(), model_source_authorization);
        let profile_id = config.worker.profile_id;
        let mut state = NativeControllerState {
            config,
            event_bus,
            supervisor: Some(supervisor),
            active: None,
            output_committer,
            input_authorization,
            output_authorization,
            provider_streams: ProviderRuntimeStreamService::new(),
            provider_bridge_attempt: Arc::new(Mutex::new(None)),
            model_source_registry,
            model_source_service_id: Uuid::new_v4(),
            model_source_service_generation: 1,
            next_model_source_attempt_generation: 0,
            handle_store_identity: NativeHandleStoreIdentity::new(Uuid::new_v4(), Uuid::new_v4())?,
            previous_handle_store_identity: None,
        };
        state.start_next().await?;
        let prior_attempt_id = state
            .active
            .as_ref()
            .map(|active| active.attempt_id)
            .ok_or_else(|| {
                NativeImageRuntimeError::Execution(
                    "Task403 worker fixture had no queued prior attempt".to_owned(),
                )
            })?;
        let prior_deadline = Instant::now() + Duration::from_secs(60);
        while state.active.is_some() {
            if Instant::now() >= prior_deadline {
                return Err(NativeImageRuntimeError::Execution(
                    "Task403 prior worker execution timed out".to_owned(),
                ));
            }
            let envelope = state
                .supervisor
                .as_ref()
                .ok_or_else(|| {
                    NativeImageRuntimeError::Execution("native worker disappeared".to_owned())
                })?
                .next_event(Duration::from_secs(5))
                .await;
            match envelope {
                Ok(envelope) => state.apply_worker_event(envelope).await?,
                Err(RuntimeSupervisorError::Timeout { .. }) => {}
                Err(error) => state.recover_worker(error).await?,
            }
        }
        let prior_snapshot = state
            .config
            .presentation
            .snapshot(profile_id)
            .map_err(|error| NativeImageRuntimeError::Execution(error.to_string()))?;
        let prior = prior_snapshot
            .attempts
            .iter()
            .find(|attempt| attempt.attempt_id == prior_attempt_id)
            .ok_or_else(|| {
                NativeImageRuntimeError::Execution("Task403 prior attempt disappeared".to_owned())
            })?;
        if prior.state != AttemptState::Succeeded {
            return Err(NativeImageRuntimeError::Execution(format!(
                "Task403 prior worker execution did not succeed: {prior:?}"
            )));
        }
        let retry_source = if replacement_plan.is_some() {
            crate::RetryPromptSource::CurrentWorkflow {
                revision: "task403-mismatch".to_owned(),
            }
        } else {
            crate::RetryPromptSource::OriginalPrompt
        };
        let retry_command = ExecutionControlCommand {
            request_id: sim_types::RequestId(Uuid::new_v4()),
            profile_id,
            expected_revision: None,
            kind: ExecutionControlCommandKind::Retry {
                attempt_id: prior_attempt_id,
                source: retry_source,
                replacement_plan,
            },
        };
        let acknowledgement = state
            .config
            .presentation
            .dispatch_durable(retry_command, &Task403RetryActivation)
            .await
            .map_err(|error| NativeImageRuntimeError::Execution(error.to_string()))?;
        let crate::ExecutionCommandOutcome::Accepted {
            assigned_attempt_id: Some(retry_attempt_id),
        } = acknowledgement.outcome
        else {
            return Err(NativeImageRuntimeError::Execution(
                "Task403 retry was not accepted".to_owned(),
            ));
        };
        state
            .supervisor
            .as_mut()
            .ok_or_else(|| {
                NativeImageRuntimeError::Execution("native worker disappeared".to_owned())
            })?
            .terminate()
            .await
            .map_err(|error| NativeImageRuntimeError::Execution(error.to_string()))?;
        state
            .recover_worker(RuntimeSupervisorError::ChannelClosed)
            .await?;
        let replacement_process_id = state
            .supervisor
            .as_ref()
            .and_then(RuntimeSupervisor::worker_process_id)
            .ok_or_else(|| {
                NativeImageRuntimeError::Execution(
                    "replacement native worker has no process ID".to_owned(),
                )
            })?;
        let replacement_identity = state.handle_store_identity;
        state.start_next().await?;
        let active = state.active.as_ref().ok_or_else(|| {
            NativeImageRuntimeError::Execution("Task403 retry did not start".to_owned())
        })?;
        let reconstruction_count = active.conditioning_control_reconstruction.len();
        let conditioning_control_reconstruction =
            active.conditioning_control_reconstruction.clone();
        let mut fresh_output_generation = false;
        let mut positive_negative_distinct = false;
        let mut predecessor_order_preserved = false;
        let mut vae_rebind_preserved = false;
        let mut stale_handle_wrong_generation = false;
        let mut no_publication_on_mismatch = false;
        let mut failure_message = None;
        let retry_deadline = Instant::now() + Duration::from_secs(60);
        while state.active.is_some() {
            if Instant::now() >= retry_deadline {
                return Err(NativeImageRuntimeError::Execution(
                    "Task403 replacement worker execution timed out".to_owned(),
                ));
            }
            let envelope = state
                .supervisor
                .as_ref()
                .ok_or_else(|| {
                    NativeImageRuntimeError::Execution("replacement worker disappeared".to_owned())
                })?
                .next_event(Duration::from_secs(5))
                .await;
            match envelope {
                Ok(envelope) => {
                    if let sim_types::WorkerMessage::Event { event } = &envelope.message {
                        match decode_native_image_worker_event(event)? {
                            NativeImageWorkerEvent::Completed { result } => {
                                let ui_outputs = result.decode_ui_outputs()?;
                                stale_handle_wrong_generation = ui_outputs.values().any(|ui| {
                                    ui.get("task402_handle_store_replacement")
                                        .and_then(|witness| witness.get("old_handle_error"))
                                        .and_then(Value::as_str)
                                        == Some("WrongGeneration")
                                });
                                no_publication_on_mismatch = ui_outputs.values().any(|ui| {
                                    ui.get("task403_no_published_handles")
                                        .and_then(Value::as_bool)
                                        == Some(true)
                                });
                                if result.report.state == AttemptState::Succeeded {
                                    for (node_id, expected) in &conditioning_control_reconstruction
                                    {
                                        let ui = ui_outputs
                                            .get(node_id)
                                            .and_then(Value::as_object)
                                            .ok_or_else(|| {
                                                NativeImageRuntimeError::WorkerEvent(
                                                    "Task403 replacement omitted reconstruction UI"
                                                        .to_owned(),
                                                )
                                            })?;
                                        let actual: PersistedNativeConditioningControlEvidence =
                                            serde_json::from_value(
                                                ui.get(crate::persistence::NATIVE_CONDITIONING_CONTROL_EVIDENCE_UI_KEY)
                                                    .cloned()
                                                    .ok_or_else(|| NativeImageRuntimeError::WorkerEvent(
                                                        "Task403 replacement omitted reconstruction evidence".to_owned(),
                                                    ))?,
                                            )
                                            .map_err(|error| NativeImageRuntimeError::Encoding(error.to_string()))?;
                                        actual.validate()?;
                                        fresh_output_generation = actual == *expected;
                                        positive_negative_distinct =
                                            actual.positive_digest != actual.negative_digest;
                                        predecessor_order_preserved =
                                            ui.get("task403_chain_nodes").and_then(Value::as_u64)
                                                == Some(2);
                                        vae_rebind_preserved = ui
                                            .get("task403_vae_execution_digest")
                                            .and_then(Value::as_str)
                                            == expected.rebind_vae_digest.as_deref();
                                    }
                                } else {
                                    failure_message = result.report.error.clone();
                                }
                            }
                            NativeImageWorkerEvent::Failed { message, .. } => {
                                failure_message = Some(message);
                            }
                            NativeImageWorkerEvent::Progress { .. }
                            | NativeImageWorkerEvent::BackendUnavailable { .. } => {}
                        }
                    }
                    state.apply_worker_event(envelope).await?;
                }
                Err(RuntimeSupervisorError::Timeout { .. }) => {}
                Err(error) => state.recover_worker(error).await?,
            }
        }
        fresh_output_generation &= stale_handle_wrong_generation
            && replacement_identity
                != state
                    .previous_handle_store_identity
                    .unwrap_or(replacement_identity);
        if let Some(supervisor) = state.supervisor.as_mut() {
            supervisor
                .terminate()
                .await
                .map_err(|error| NativeImageRuntimeError::Execution(error.to_string()))?;
        }
        let snapshot = state
            .config
            .presentation
            .snapshot(profile_id)
            .map_err(|error| NativeImageRuntimeError::Execution(error.to_string()))?;
        let retry = snapshot
            .attempts
            .iter()
            .find(|attempt| attempt.attempt_id == retry_attempt_id)
            .ok_or_else(|| {
                NativeImageRuntimeError::Execution("Task403 retry disappeared".to_owned())
            })?;
        Ok(NativeConditioningControlWorkerReplacementEvidence {
            original_process_id,
            replacement_process_id,
            retry_attempt_id,
            reconstruction_count,
            fresh_output_generation,
            positive_negative_distinct,
            predecessor_order_preserved,
            vae_rebind_preserved,
            stale_handle_wrong_generation,
            no_publication_on_mismatch,
            terminal_state: retry.state,
            failure_message,
        })
    })
}

