    #[test]
    fn clip_text_entry_publishes_explicit_none_or_original_pooled_alias_and_distinct_digests()
    -> anyhow::Result<()> {
        use sim_model::conditioning::{ConditioningMetadataKey, ConditioningMetadataValue};
        let (backend, authority) = CpuWorkspaceAuthority::create_backend(1 << 20)?;
        let cancellation = CancellationToken::default();
        let execution = backend.execution_context(
            StreamId::DEFAULT,
            authority.authorize_workspace(1 << 20)?,
            &cancellation,
        );
        let primary = tensor_from_f32(&backend, &[1, 1, 2], &[1.0, 2.0], &execution)?;
        let pooled = tensor_from_f32(&backend, &[3], &[3.0, 4.0, 5.0], &execution)?;
        let none = clip_text_conditioning_entry(primary.clone(), None)?;
        assert!(matches!(
            none.metadata().get(ConditioningMetadataKey::PooledOutput),
            Some(ConditioningMetadataValue::PooledOutput(None))
        ));
        let some = clip_text_conditioning_entry(primary.clone(), Some(&pooled))?;
        assert!(
            matches!(some.metadata().get(ConditioningMetadataKey::PooledOutput),Some(ConditioningMetadataValue::PooledOutput(Some(value))) if value.storage_id()==pooled.storage_id())
        );
        assert!(
            some.metadata()
                .get(ConditioningMetadataKey::PooledOutputControlnet)
                .is_none()
        );
        let ConditioningValue::CrossAttention(value) = some.value() else {
            anyhow::bail!("primary conditioning lost");
        };
        assert_eq!(value.storage_id(), primary.storage_id());
        let identity = ConditioningIdentity::new(
            "sd15-clip-text",
            sd15_model_family_identity()?,
            sd15_latent_format_identity()?,
        )?;
        let absent = ConditioningSet::checked(
            identity.clone(),
            vec![ConditioningEntry::checked(
                "cross-attention",
                ConditioningValue::cross_attention(primary.clone())?,
                Default::default(),
            )?],
            &cancellation,
        )?;
        let none = ConditioningSet::checked(identity.clone(), vec![none], &cancellation)?;
        let some = ConditioningSet::checked(identity, vec![some], &cancellation)?;
        assert_ne!(absent.digest(), none.digest());
        assert_ne!(none.digest(), some.digest());
        assert_eq!(none.resident_parts()?.tensor_allocations().len(), 1);
        assert_eq!(some.resident_parts()?.tensor_allocations().len(), 2);
        for tensor in [&primary, &pooled] {
            let parts = some.resident_parts()?;
            let allocations = parts
                .tensor_allocations()
                .iter()
                .filter(|item| item.storage_id() == tensor.storage_id())
                .collect::<Vec<_>>();
            let [allocation] = allocations.as_slice() else {
                anyhow::bail!("storage allocation counted incorrectly");
            };
            assert_eq!(allocation.resident_bytes(), tensor.storage_byte_len());
        }
        Ok(())
    }

    #[test]
    fn clip_text_entry_preserves_same_storage_pool_alias_and_canonical_cancel_or_empty_rejection()
    -> anyhow::Result<()> {
        use sim_model::conditioning::{
            ConditioningError, ConditioningMetadataKey, ConditioningMetadataValue,
        };
        let (backend, authority) = CpuWorkspaceAuthority::create_backend(1 << 20)?;
        let cancellation = CancellationToken::default();
        let execution = backend.execution_context(
            StreamId::DEFAULT,
            authority.authorize_workspace(1 << 20)?,
            &cancellation,
        );
        let primary = tensor_from_f32(&backend, &[1, 1, 2], &[1.0, 2.0], &execution)?;
        let entry = clip_text_conditioning_entry(primary.clone(), Some(&primary))?;
        assert!(
            matches!(entry.metadata().get(ConditioningMetadataKey::PooledOutput),Some(ConditioningMetadataValue::PooledOutput(Some(value))) if value.storage_id()==primary.storage_id())
        );
        let identity = ConditioningIdentity::new(
            "sd15-clip-text",
            sd15_model_family_identity()?,
            sd15_latent_format_identity()?,
        )?;
        let set = ConditioningSet::checked(identity.clone(), vec![entry.clone()], &cancellation)?;
        assert_eq!(set.resident_parts()?.tensor_allocations().len(), 1);
        let digest = set.digest().to_owned();
        let cancelled = CancellationToken::default();
        cancelled.cancel();
        assert!(matches!(
            ConditioningSet::checked(identity.clone(), vec![entry.clone()], &cancelled),
            Err(ConditioningError::Cancelled)
        ));
        assert_eq!(set.digest(), digest);
        let recovered = ConditioningSet::checked(identity, vec![entry], &cancellation)?;
        assert_eq!(recovered.digest(), digest);
        for (shape, values) in [(&[][..], &[1.0][..]), (&[0][..], &[][..])] {
            let unsupported = tensor_from_f32(&backend, shape, values, &execution)?;
            assert!(matches!(
                clip_text_conditioning_entry(primary.clone(), Some(&unsupported)),
                Err(ConditioningError::Invalid(_))
            ));
        }
        Ok(())
    }

    #[test]
    fn model_resource_loader_accepts_only_scalar_source_string_and_combo_filenames()
    -> anyhow::Result<()> {
        let loader = NativeModelResourceLoaderNode {
            class_type: "AudioEncoderLoader".to_owned(),
            implementation_version: "test".to_owned(),
            recipes: AUDIO_MODEL_RESOURCE_RECIPES,
        };
        for value in [
            NativeValue::Primitive {
                value: NativePrimitive::String("encoder.safetensors".to_owned()),
            },
            NativeValue::PreservedUnknown {
                type_name: "COMBO".to_owned(),
                value: json!("encoder.safetensors"),
            },
        ] {
            let inputs = BTreeMap::from([("audio_encoder_name".to_owned(), value.clone())]);
            assert_eq!(loader.requests(&inputs)?.len(), 1);
            assert_eq!(
                required_source_string(&inputs, "audio_encoder_name")?,
                "encoder.safetensors"
            );
            if matches!(value, NativeValue::PreservedUnknown { .. }) {
                assert!(required_string(&inputs, "audio_encoder_name").is_err());
                let mapped = BTreeMap::from([(
                    "optimizer".to_owned(),
                    NativeValue::List {
                        values: vec![value],
                    },
                )]);
                assert_eq!(
                    training_required_string(&mapped, "optimizer")?,
                    "encoder.safetensors"
                );
            }
        }
        for value in [
            NativeValue::PreservedUnknown {
                type_name: "STRING".to_owned(),
                value: json!("encoder.safetensors"),
            },
            NativeValue::PreservedUnknown {
                type_name: "COMBO".to_owned(),
                value: json!(["encoder.safetensors"]),
            },
            NativeValue::List {
                values: vec![NativeValue::Primitive {
                    value: NativePrimitive::String("encoder.safetensors".to_owned()),
                }],
            },
        ] {
            let inputs = BTreeMap::from([("audio_encoder_name".to_owned(), value)]);
            assert!(loader.requests(&inputs).is_err());
        }
        assert!(loader.requests(&BTreeMap::new()).is_err());
        Ok(())
    }

    #[derive(Debug)]
    struct LatentPublicationBoundary {
        inner: Arc<dyn sim_nodes::NativeHandleStore>,
        remaining: std::sync::atomic::AtomicUsize,
        reject: bool,
    }
    impl sim_nodes::NativeHandleStore for LatentPublicationBoundary {
        fn identity(&self) -> sim_nodes::NativeHandleStoreIdentity {
            self.inner.identity()
        }
        fn attempt_id(&self) -> AttemptId {
            self.inner.attempt_id()
        }
        fn resolve(
            &self,
            handle: &sim_nodes::NativeOpaqueHandle,
            expected: &sim_nodes::NativeHandleType,
            cancellation: &CancellationToken,
        ) -> Result<sim_nodes::NativeResolvedPayload, sim_nodes::NativeHandleStoreError> {
            self.inner.resolve(handle, expected, cancellation)
        }
        fn publish(
            &self,
            payload: NativeStoredPayload,
            cancellation: &CancellationToken,
        ) -> Result<sim_nodes::NativeOpaqueHandle, sim_nodes::NativeHandleStoreError> {
            let trigger = self
                .remaining
                .fetch_sub(1, std::sync::atomic::Ordering::SeqCst)
                == 1;
            if trigger && self.reject {
                return Err(sim_nodes::NativeHandleStoreError::Rejected(
                    "test output capacity exhausted".to_owned(),
                ));
            }
            let handle = self.inner.publish(payload, cancellation)?;
            if trigger {
                cancellation.cancel();
            }
            Ok(handle)
        }
        fn revoke(
            &self,
            handle: &sim_nodes::NativeOpaqueHandle,
            cancellation: &CancellationToken,
        ) -> Result<(), sim_nodes::NativeHandleStoreError> {
            self.inner.revoke(handle, cancellation)
        }
    }

    #[test]
    fn empty_latent_publication_failure_and_late_cancellation_are_atomic()
    -> Result<(), Box<dyn std::error::Error>> {
        let (backend, authority) = CpuWorkspaceAuthority::create_backend(1024 * 1024)?;
        let node = EmptyLatentNode {
            backend: Arc::new(backend),
        };
        let generation = NativeHandleStoreGeneration::new()?;
        let attempt = AttemptId(Uuid::from_u128(0x628b00));
        let inputs = BTreeMap::from([
            (
                "width".to_owned(),
                NativeValue::Primitive {
                    value: NativePrimitive::UnsignedInteger(64),
                },
            ),
            (
                "height".to_owned(),
                NativeValue::Primitive {
                    value: NativePrimitive::UnsignedInteger(64),
                },
            ),
            (
                "batch_size".to_owned(),
                NativeValue::Primitive {
                    value: NativePrimitive::UnsignedInteger(1),
                },
            ),
        ]);
        for reject in [true, false] {
            let context = NodeContext::new(
                PromptId(Uuid::from_u128(0x628b01)),
                attempt,
                NodeId("empty".to_owned()),
                CancellationToken::default(),
                authority.authorize_workspace(1024 * 1024)?,
                Arc::new(LatentPublicationBoundary {
                    inner: generation.handle_store_for_attempt(attempt),
                    remaining: AtomicUsize::new(1),
                    reject,
                }),
            )?;
            let failure = smol::block_on(node.execute(context, inputs.clone()))
                .err()
                .ok_or("Failed latent publication succeeded")?;
            assert_eq!(
                failure.kind,
                if reject {
                    NodeFailureKind::Failure
                } else {
                    NodeFailureKind::Interrupted
                }
            );
            assert!(generation.is_empty());
        }
        let context = NodeContext::new(
            PromptId(Uuid::from_u128(0x628b01)),
            attempt,
            NodeId("empty".to_owned()),
            CancellationToken::default(),
            authority.authorize_workspace(1024 * 1024)?,
            generation.handle_store_for_attempt(attempt),
        )?;
        let NodeOutcome::Values { outputs, .. } =
            smol::block_on(node.execute(context.clone(), inputs))?
        else {
            return Err("Expected latent output".into());
        };
        let Some(NativeValue::Handle { value: handle }) = outputs.first() else {
            return Err("Missing latent handle".into());
        };
        let payload =
            context
                .handle_store()
                .resolve(handle, handle.handle_type(), &context.cancellation)?;
        let NativeStoredPayload::Latent(bundle) = payload.as_ref() else {
            return Err("Expected latent bundle".into());
        };
        assert_eq!(
            bundle
                .samples()
                .tensor()
                .ok_or("Missing samples")?
                .descriptor()
                .shape(),
            &[1, 4, 8, 8]
        );
        assert_eq!(generation.len(), 1);
        Ok(())
    }

    #[derive(Debug)]
    struct TrainingLoraAssetResolver {
        identity: NativeNodeServiceIdentity,
        name: String,
        reference: sim_nodes::NativeAssetReference,
        bytes: Arc<[u8]>,
    }

    impl sim_nodes::NativeAssetResolver for TrainingLoraAssetResolver {
        fn identity(&self) -> &NativeNodeServiceIdentity {
            &self.identity
        }

        fn list_names(
            &self,
            request: &sim_nodes::NativeAssetNameListRequest,
            _cancellation: &CancellationToken,
        ) -> Result<sim_nodes::NativeAssetNameList, sim_nodes::NativeAssetServiceError> {
            sim_nodes::NativeAssetNameList::checked(
                request.folder_category(),
                vec![self.name.clone()],
            )
        }

        fn resolve_names(
            &self,
            request: &NativeAssetNameResolutionRequest,
            _cancellation: &CancellationToken,
        ) -> Result<sim_nodes::NativeAssetNameResolution, sim_nodes::NativeAssetServiceError>
        {
            if request.folder_category() != "loras"
                || request.source_type_id() != "LORA_MODEL"
                || request.names() != [self.name.clone()]
            {
                return Err(sim_nodes::NativeAssetServiceError::InvalidRequest);
            }
            sim_nodes::NativeAssetNameResolution::checked(
                "loras",
                vec![sim_nodes::NativeNamedAssetReference::checked(
                    self.name.clone(),
                    self.reference.clone(),
                )?],
            )
        }

        fn read_verified(
            &self,
            request: &NativeAssetReadRequest,
            cancellation: &CancellationToken,
        ) -> Result<sim_nodes::NativeResolvedAsset, sim_nodes::NativeAssetServiceError> {
            cancellation
                .check()
                .map_err(|_| sim_nodes::NativeAssetServiceError::Cancelled)?;
            if request.reference() != &self.reference
                || request.maximum_bytes() < self.reference.byte_length()
            {
                return Err(sim_nodes::NativeAssetServiceError::InvalidRequest);
            }
            sim_nodes::NativeResolvedAsset::checked(
                self.reference.clone(),
                self.bytes.clone(),
                self.reference.sha256(),
            )
        }
    }

    fn loaded_model_resource_raft(
        cancellation: &CancellationToken,
    ) -> Result<Arc<sim_model::NativeRaftLarge>, Box<dyn std::error::Error>> {
        let (backend, workspace_authority) =
            CpuWorkspaceAuthority::create_backend(64 * 1024 * 1024)?;
        let mut raft = sim_model::raft_large_exact_native(false, false, cancellation)?;
        let mut shared_tensors: Vec<(Vec<u64>, DType, Tensor)> = Vec::new();
        let mut state = BTreeMap::new();
        for specification in raft.state_schema() {
            cancellation.check()?;
            let tensor = match shared_tensors.iter().find(|(shape, dtype, _)| {
                shape == &specification.shape && *dtype == specification.dtype
            }) {
                Some((_, _, tensor)) => tensor.clone(),
                None => {
                    let encoded_bytes = specification
                        .shape
                        .iter()
                        .try_fold(specification.dtype.byte_width(), |bytes, dimension| {
                            bytes.checked_mul(*dimension)
                        })
                        .ok_or("RAFT fixture byte count overflowed")?;
                    let descriptor = TensorDescriptor::contiguous(
                        specification.shape.clone(),
                        specification.dtype,
                        DeviceId::CPU,
                        StreamId::DEFAULT,
                    )?;
                    let context = backend.execution_context(
                        StreamId::DEFAULT,
                        workspace_authority.authorize_workspace(encoded_bytes.max(1))?,
                        cancellation,
                    );
                    let tensor = backend
                        .upload_bytes(
                            descriptor,
                            &vec![0_u8; usize::try_from(encoded_bytes)?],
                            &context,
                        )?
                        .0;
                    shared_tensors.push((
                        specification.shape.clone(),
                        specification.dtype,
                        tensor.clone(),
                    ));
                    tensor
                }
            };
            state.insert(specification.name.clone(), tensor);
        }
        raft.load_state_dict(state, cancellation)?;
        raft.eval();
        Ok(Arc::new(raft))
    }

    #[test]
    fn native_model_resource_execution_publishes_once_and_fails_atomically()
    -> Result<(), Box<dyn std::error::Error>> {
        let cancellation = CancellationToken::default();
        let raft = loaded_model_resource_raft(&cancellation)?;
        let resource = Arc::new(NativeModelPayload::optical_flow(raft)?);
        let stored = NativeStoredModelPayload::model_resource(resource.clone())?;
        let resident_bytes = stored.resident_bytes()?;
        let generation = NativeHandleStoreGeneration::with_capacities(1, resident_bytes)?;
        let attempt_id = AttemptId(Uuid::from_u128(0x4020));
        let handle_store = generation.handle_store_for_attempt(attempt_id);
        let (_backend, workspace_authority) = CpuWorkspaceAuthority::create_backend(1)?;
        let context = NodeContext::new(
            PromptId(Uuid::from_u128(0x4021)),
            attempt_id,
            NodeId("native-model-resource".to_owned()),
            cancellation.clone(),
            workspace_authority.authorize_workspace(1)?,
            handle_store.clone(),
        )?;

        let NativeValue::Handle { value: handle } = publish_reconstructed_native_model_resource(
            resource.clone(),
            resource.identity().digest_sha256(),
            &context,
        )?
        else {
            return Err("model resource publisher returned a non-handle value".into());
        };
        let resolved_payload =
            handle_store.resolve(&handle, handle.handle_type(), &cancellation)?;
        let NativeStoredPayload::Model(resolved_model) = resolved_payload.as_ref() else {
            return Err("model resource handle resolved to another payload kind".into());
        };
        assert_eq!(
            resolved_model.model_payload().identity().digest_sha256(),
            resource.identity().digest_sha256()
        );
        drop(resolved_payload);
        handle_store.revoke(&handle, &cancellation)?;
        assert!(generation.is_empty());

        let cancelled = CancellationToken::default();
        cancelled.cancel();
        let cancelled_context = NodeContext::new(
            PromptId(Uuid::from_u128(0x4022)),
            attempt_id,
            NodeId("cancelled-native-model-resource".to_owned()),
            cancelled,
            workspace_authority.authorize_workspace(1)?,
            handle_store,
        )?;
        let failure = publish_native_model_resource(resource.clone(), &cancelled_context)
            .expect_err("cancelled model resource publication unexpectedly succeeded");
        assert_eq!(failure.kind, NodeFailureKind::Interrupted);
        assert!(generation.is_empty());

        let constrained = NativeHandleStoreGeneration::with_capacities(
            1,
            resident_bytes
                .checked_sub(1)
                .ok_or("model resource residency was unexpectedly zero")?,
        )?;
        let constrained_store = constrained.handle_store_for_attempt(attempt_id);
        let constrained_context = NodeContext::new(
            PromptId(Uuid::from_u128(0x4023)),
            attempt_id,
            NodeId("oom-native-model-resource".to_owned()),
            CancellationToken::default(),
            workspace_authority.authorize_workspace(1)?,
            constrained_store,
        )?;
        let changed = publish_reconstructed_native_model_resource(
            resource.clone(),
            &"0".repeat(64),
            &constrained_context,
        )
        .expect_err("changed reconstruction identity unexpectedly published");
        assert_eq!(changed.code, "native_model_resource_reconstruction_changed");
        assert!(constrained.is_empty());
        assert!(publish_native_model_resource(resource, &constrained_context).is_err());
        assert!(constrained.is_empty());
        Ok(())
    }

