    fn native(value: Value) -> NativeValue {
        match value {
            Value::Null => NativeValue::Primitive {
                value: NativePrimitive::Null,
            },
            Value::Bool(value) => NativeValue::Primitive {
                value: NativePrimitive::Boolean(value),
            },
            Value::Number(value) => {
                if let Some(value) = value.as_i64() {
                    NativeValue::Primitive {
                        value: NativePrimitive::Integer(value),
                    }
                } else if let Some(value) = value.as_u64() {
                    NativeValue::Primitive {
                        value: NativePrimitive::UnsignedInteger(value),
                    }
                } else if let Some(value) = value.as_f64() {
                    NativeValue::Primitive {
                        value: NativePrimitive::Number(value),
                    }
                } else {
                    NativeValue::PreservedUnknown {
                        type_name: "zed.json-number@1".to_owned(),
                        value: Value::Number(value),
                    }
                }
            }
            Value::String(value) => NativeValue::Primitive {
                value: NativePrimitive::String(value),
            },
            value => NativeValue::PreservedUnknown {
                type_name: "zed.json@1".to_owned(),
                value,
            },
        }
    }

    #[test]
    fn multimodal_text_generation_rejects_wrong_and_stale_handles_without_publication()
    -> Result<(), Box<dyn std::error::Error>> {
        let (backend, workspace_authority) = CpuWorkspaceAuthority::create_backend(1 << 20)?;
        let cancellation = CancellationToken::default();
        let scratch = workspace_authority.authorize_workspace(1 << 20)?;
        let tensor_context = ExecutionContext {
            stream: StreamId::DEFAULT,
            scratch: scratch.clone(),
            rng_phase: None,
            cancellation: &cancellation,
        };
        let image = ImageTensor::from_f32(&backend, &tensor_context, 1, 1, 1, 3, &[0.0, 0.5, 1.0])?;
        drop(tensor_context);
        let attempt_id = AttemptId(Uuid::from_u128(0x3991));
        let generation = NativeHandleStoreGeneration::new()?;
        let store = generation.handle_store_for_attempt(attempt_id);
        let context = NodeContext::new(
            PromptId(Uuid::from_u128(0x3990)),
            attempt_id,
            NodeId("multimodal-text".to_owned()),
            cancellation.clone(),
            scratch,
            store.clone(),
        )?;
        let payload = NativeTensorPayload::from_image(NativeTensorRole::Image, image)?;
        let wrong_clip = store.publish(
            NativeStoredPayload::Tensor(Arc::new(payload)),
            &cancellation,
        )?;
        let request = NativeMultimodalTextGenerationRequest {
            text: NativeTextGenerationRequest {
                formatted_prompt: "test",
                maximum_new_tokens: 1,
                do_sample: false,
                temperature_bits: 1.0_f32.to_bits(),
                top_k: 50,
                top_p_bits: 1.0_f32.to_bits(),
                minimum_p_bits: 0.0_f32.to_bits(),
                repetition_penalty_bits: 1.0_f32.to_bits(),
                presence_penalty_bits: 0.0_f32.to_bits(),
            },
            use_default_template: true,
            thinking: false,
        };
        let resident_bytes = generation.resident_bytes();
        let error = execute_native_multimodal_text_generation(
            &context,
            &wrong_clip,
            None,
            None,
            None,
            7,
            request.clone(),
        )
        .err()
        .ok_or("IMAGE handle unexpectedly resolved as a multimodal CLIP")?;
        assert_eq!(error.kind, NodeFailureKind::Failure);
        assert_eq!(generation.len(), 1);
        assert_eq!(generation.resident_bytes(), resident_bytes);

        let service_identity = NativeNodeServiceIdentity::checked(
            Uuid::from_u128(0x3992),
            attempt_id,
            context.node_id.clone(),
        )?;
        let services = sim_nodes::NativeNodeServices::checked(None, None, None)?
            .with_text_generation(Arc::new(NativeRuntimeTextGenerationService::new(
                service_identity,
            )))?;
        let service_context = NodeContext::new_with_services(
            context.prompt_id,
            attempt_id,
            context.node_id.clone(),
            cancellation.clone(),
            workspace_authority.authorize_workspace(1 << 20)?,
            store.clone(),
            services,
        )?;
        let missing_clip = NativeOpaqueHandle::new(
            NativeHandleType::new(NativeHandleKind::Clip, "CLIP")?,
            wrong_clip.store_identity(),
            "missing-clip",
            1,
            Some("f".repeat(64)),
        )?;
        let service_request = NativeNodeMultimodalTextGenerationRequest::checked(
            missing_clip,
            None,
            None,
            None,
            "test",
            1,
            false,
            1.0_f32.to_bits(),
            50,
            1.0_f32.to_bits(),
            0.0_f32.to_bits(),
            1.0_f32.to_bits(),
            0.0_f32.to_bits(),
            7,
            true,
            false,
        )?;
        assert!(matches!(
            service_context.execute_multimodal_text_generation(&service_request),
            Err(NativeTextGenerationServiceError::Execution(_))
        ));
        assert_eq!(generation.len(), 1);
        assert_eq!(generation.resident_bytes(), resident_bytes);

        let restarted = NativeHandleStoreGeneration::new()?;
        let restarted_store = restarted.handle_store_for_attempt(attempt_id);
        let restarted_context = NodeContext::new(
            context.prompt_id,
            attempt_id,
            context.node_id.clone(),
            cancellation.clone(),
            workspace_authority.authorize_workspace(1 << 20)?,
            restarted_store,
        )?;
        let stale_error = execute_native_multimodal_text_generation(
            &restarted_context,
            &wrong_clip,
            None,
            None,
            None,
            7,
            request.clone(),
        )
        .err()
        .ok_or("old-generation handle unexpectedly resolved after restart")?;
        assert_eq!(stale_error.kind, NodeFailureKind::Failure);
        assert!(restarted.is_empty());
        assert_eq!(restarted.resident_bytes(), 0);

        cancellation.cancel();
        let cancelled = execute_native_multimodal_text_generation(
            &context,
            &wrong_clip,
            None,
            None,
            None,
            7,
            request,
        )
        .err()
        .ok_or("pre-cancelled generation unexpectedly succeeded")?;
        assert_eq!(cancelled.kind, NodeFailureKind::Interrupted);
        assert_eq!(generation.len(), 1);
        assert_eq!(generation.resident_bytes(), resident_bytes);
        Ok(())
    }

    #[test]
    fn shader_identity_is_stable_across_restart_and_partitions_cache_configuration()
    -> Result<(), Box<dyn std::error::Error>> {
        let registry = native_image_registry_projection()?;
        let plan = PromptCompiler::new(&registry).compile(fixture_prompt())?;
        let profile_id = ProfileId(Uuid::from_u128(0x5349_4d00_0000_0000_0000_0000_0000_377));
        let (first_backend, _) =
            CpuWorkspaceAuthority::create_backend(DEFAULT_NATIVE_IMAGE_MEMORY_LIMIT_BYTES)?;
        let first = NativeImageExecutor::new_with_cpu_backend(
            profile_id,
            BTreeMap::new(),
            true,
            Arc::new(first_backend),
        )?
        .with_shader_executor(Arc::new(IdentityShaderExecutor("shader-a")));
        let first_identity = first.execution_configuration_token(&plan, "balanced");
        assert!(first_identity.ends_with(&format!(
            ":shader=shader-a:training={NATIVE_MODEL_TRAINING_SERVICE_VERSION}"
        )));

        let (restarted_backend, _) =
            CpuWorkspaceAuthority::create_backend(DEFAULT_NATIVE_IMAGE_MEMORY_LIMIT_BYTES)?;
        let restarted = NativeImageExecutor::new_with_cpu_backend(
            profile_id,
            BTreeMap::new(),
            true,
            Arc::new(restarted_backend),
        )?
        .with_shader_executor(Arc::new(IdentityShaderExecutor("shader-a")));
        assert_eq!(
            restarted.execution_configuration_token(&plan, "balanced"),
            first_identity
        );

        let (changed_backend, _) =
            CpuWorkspaceAuthority::create_backend(DEFAULT_NATIVE_IMAGE_MEMORY_LIMIT_BYTES)?;
        let changed = NativeImageExecutor::new_with_cpu_backend(
            profile_id,
            BTreeMap::new(),
            true,
            Arc::new(changed_backend),
        )?
        .with_shader_executor(Arc::new(IdentityShaderExecutor("shader-b")));
        assert_ne!(
            changed.execution_configuration_token(&plan, "balanced"),
            first_identity
        );

        let (ltxv_backend, _) =
            CpuWorkspaceAuthority::create_backend(DEFAULT_NATIVE_IMAGE_MEMORY_LIMIT_BYTES)?;
        let ltxv = NativeImageExecutor::new_with_cpu_backend(
            profile_id,
            BTreeMap::new(),
            true,
            Arc::new(ltxv_backend),
        )?
        .with_shader_executor(Arc::new(IdentityShaderExecutor("shader-a")))
        .with_ltxv_preprocess_service(Arc::new(IdentityLtxvPreprocessService {
            identity: sim_nodes::NativeLtxvPreprocessServiceIdentity::checked("d".repeat(64))?,
        }));
        let ltxv_identity = ltxv.execution_configuration_token(&plan, "balanced");
        assert!(ltxv_identity.ends_with(&format!(":ltxv={}", "d".repeat(64))));
        assert_ne!(ltxv_identity, first_identity);

        let (webm_backend, _) =
            CpuWorkspaceAuthority::create_backend(DEFAULT_NATIVE_IMAGE_MEMORY_LIMIT_BYTES)?;
        let webm = NativeImageExecutor::new_with_cpu_backend(
            profile_id,
            BTreeMap::new(),
            true,
            Arc::new(webm_backend),
        )?
        .with_shader_executor(Arc::new(IdentityShaderExecutor("shader-a")))
        .with_webm_encode_service(Arc::new(IdentityWebmEncodeService {
            identity: sim_nodes::NativeWebmEncodeServiceIdentity::checked("e".repeat(64))?,
        }));
        let webm_identity = webm.execution_configuration_token(&plan, "balanced");
        assert!(webm_identity.ends_with(&format!(":webm={}", "e".repeat(64))));
        assert_ne!(webm_identity, first_identity);

        let (h264_mp4_backend, _) =
            CpuWorkspaceAuthority::create_backend(DEFAULT_NATIVE_IMAGE_MEMORY_LIMIT_BYTES)?;
        let h264_mp4 = NativeImageExecutor::new_with_cpu_backend(
            profile_id,
            BTreeMap::new(),
            true,
            Arc::new(h264_mp4_backend),
        )?
        .with_shader_executor(Arc::new(IdentityShaderExecutor("shader-a")))
        .with_component_h264_mp4_backing_service(Arc::new(
            IdentityComponentH264Mp4BackingService {
                identity: sim_nodes::NativeComponentH264Mp4BackingServiceIdentity::checked(
                    "f".repeat(64),
                )?,
            },
        ));
        let h264_mp4_identity = h264_mp4.execution_configuration_token(&plan, "balanced");
        assert!(h264_mp4_identity.ends_with(&format!(":h264-mp4={}", "f".repeat(64))));
        assert_ne!(h264_mp4_identity, first_identity);

        let (both_backend, _) =
            CpuWorkspaceAuthority::create_backend(DEFAULT_NATIVE_IMAGE_MEMORY_LIMIT_BYTES)?;
        let both = NativeImageExecutor::new_with_cpu_backend(
            profile_id,
            BTreeMap::new(),
            true,
            Arc::new(both_backend),
        )?
        .with_shader_executor(Arc::new(IdentityShaderExecutor("shader-a")))
        .with_ltxv_preprocess_service(Arc::new(IdentityLtxvPreprocessService {
            identity: sim_nodes::NativeLtxvPreprocessServiceIdentity::checked("d".repeat(64))?,
        }))
        .with_webm_encode_service(Arc::new(IdentityWebmEncodeService {
            identity: sim_nodes::NativeWebmEncodeServiceIdentity::checked("e".repeat(64))?,
        }))
        .with_component_h264_mp4_backing_service(Arc::new(
            IdentityComponentH264Mp4BackingService {
                identity: sim_nodes::NativeComponentH264Mp4BackingServiceIdentity::checked(
                    "f".repeat(64),
                )?,
            },
        ));
        assert!(
            both.execution_configuration_token(&plan, "balanced")
                .ends_with(&format!(
                    ":ltxv={}:webm={}:h264-mp4={}",
                    "d".repeat(64),
                    "e".repeat(64),
                    "f".repeat(64)
                ))
        );
        Ok(())
    }

    #[test]
    fn provider_registry_pin_is_canonical_and_tamper_evident() {
        let pin = NativeProviderRegistryPin::checked(
            7,
            "a".repeat(64),
            vec!["b".repeat(64), "c".repeat(64)],
        )
        .expect("sorted provider registry pin is valid");
        let encoded = serde_json::to_vec(&pin).expect("provider registry pin serializes");
        let decoded: NativeProviderRegistryPin =
            serde_json::from_slice(&encoded).expect("provider registry pin deserializes");
        assert_eq!(decoded, pin);

        for invalid in [
            NativeProviderRegistryPin::checked(0, "a".repeat(64), vec!["b".repeat(64)]),
            NativeProviderRegistryPin::checked(1, "A".repeat(64), vec!["b".repeat(64)]),
            NativeProviderRegistryPin::checked(1, "a".repeat(64), Vec::new()),
            NativeProviderRegistryPin::checked(
                1,
                "a".repeat(64),
                vec!["c".repeat(64), "b".repeat(64)],
            ),
            NativeProviderRegistryPin::checked(
                1,
                "a".repeat(64),
                vec!["b".repeat(64), "b".repeat(64)],
            ),
        ] {
            assert!(matches!(invalid, Err(NativeImageRuntimeError::Encoding(_))));
        }

        let unknown_field = serde_json::json!({
            "generation": 7,
            "registry_digest_sha256": "a".repeat(64),
            "binding_digests_sha256": ["b".repeat(64)],
            "store_generation": 99,
        });
        assert!(
            serde_json::from_value::<NativeProviderRegistryPin>(unknown_field).is_err(),
            "provider registry pins reject unknown fields"
        );
        let changed = NativeProviderRegistryPin::checked(
            8,
            "a".repeat(64),
            vec!["b".repeat(64), "c".repeat(64)],
        )
        .expect("changed provider registry pin is valid");
        assert_ne!(pin.identity_sha256(), changed.identity_sha256());
        assert!(valid_provider_registry_digest(&pin.identity_sha256()));
    }

    fn compiled_provider_plan(
        pin: NativeProviderRegistryPin,
    ) -> Result<CompiledPlan, Box<dyn std::error::Error>> {
        let descriptor = sim_nodes::NativeNodeDescriptor {
            schema_version: sim_nodes::LEGACY_NATIVE_NODE_CONTRACT_SCHEMA_VERSION,
            class_type: "ControllerProvider".to_owned(),
            implementation_version: "1".to_owned(),
            source_schema: None,
            inputs: Vec::new(),
            dynamic_inputs: Vec::new(),
            outputs: vec![sim_nodes::NativeOutputDescriptor {
                name: "value".to_owned(),
                produced_type: NativeValueType::Primitive(NativePrimitiveType::Number),
                is_list: false,
            }],
            output_node: true,
            effect: sim_nodes::NativeEffectClass::Provider,
            cache: sim_nodes::NativeCachePolicy::Never,
        };
        let mut registry = NativeNodeRegistry::default();
        registry.register_descriptor(descriptor)?;
        Ok(PromptCompiler::new(&registry)
            .with_provider_registry_pin(pin)?
            .compile(PromptSubmission {
                prompt: ApiPrompt(BTreeMap::from([(
                    NodeId::from("provider"),
                    PromptNode {
                        class_type: "ControllerProvider".to_owned(),
                        inputs: BTreeMap::new(),
                        unknown: BTreeMap::new(),
                    },
                )])),
                prompt_id: Some(PromptId(Uuid::from_u128(0x3710))),
                client_id: None,
                number: None,
                extra_data: BTreeMap::new(),
                unknown: BTreeMap::new(),
            })?)
    }

    #[test]
    fn controller_rejects_stale_provider_plan_before_dispatch()
    -> Result<(), Box<dyn std::error::Error>> {
        let planned = NativeProviderRegistryPin::checked(7, "a".repeat(64), vec!["b".repeat(64)])?;
        let plan = compiled_provider_plan(planned.clone())?;
        assert!(validate_plan_provider_registry(&plan, Some(&planned)).is_ok());
        let current = NativeProviderRegistryPin::checked(8, "c".repeat(64), vec!["d".repeat(64)])?;
        let stale = validate_plan_provider_registry(&plan, Some(&current))
            .expect_err("changed provider deployment rejects queued plan");
        assert_eq!(stale.code, "native_provider_registry_stale");
        assert_eq!(
            validate_plan_provider_registry(&plan, None)
                .expect_err("missing provider deployment rejects queued plan")
                .code,
            "native_provider_registry_stale"
        );
        let mut worker_plan = NativeImageWorkerPlan::new(plan, BTreeMap::new(), true, 0)?;
        assert_eq!(worker_plan.provider_registry.as_ref(), Some(&planned));
        worker_plan.provider_registry = None;
        assert!(matches!(
            worker_plan.validate(),
            Err(NativeImageRuntimeError::Encoding(message))
                if message.contains("derived from the compiled plan")
        ));
        Ok(())
    }

    fn empty_worker_registry_deployment(
        generation: u64,
        registry_digest_sha256: &str,
    ) -> Result<crate::WorkerRegistryDeploymentPlan, Box<dyn std::error::Error>> {
        let begin = sim_types::WorkerRegistryDeploymentBegin::new(
            sim_types::WorkerRegistryGeneration::new(generation)?,
            sim_types::WorkerSha256Digest::new(registry_digest_sha256.to_owned())?,
            Vec::new(),
        )?;
        let authorization_verifier = crate::PluginAuthorizationSealer::from_seed(
            [0x71; 32],
            crate::PermissionPolicyGeneration::new(1)?,
        )?
        .verifier()?;
        Ok(crate::WorkerRegistryDeploymentPlan::new(
            begin,
            Vec::new(),
            authorization_verifier,
        )?)
    }

    #[test]
    fn native_controller_requires_the_exact_provider_registry_deployment()
    -> Result<(), Box<dyn std::error::Error>> {
        let (_temporary, roots) = fixture_roots()?;
        let profile_id = ProfileId(Uuid::parse_str(&roots.profile_id)?);
        let mut presentation_service = ExecutionPresentationService::new(8)?;
        presentation_service.initialize_profile(
            profile_id,
            ExecutionDataSource::Live,
            ExecutionSnapshotStatus::Ready,
        )?;
        let presentation = crate::ExecutionPresentationOwner::ephemeral(presentation_service);
        let pin = NativeProviderRegistryPin::checked(7, "a".repeat(64), vec!["b".repeat(64)])?;
        let worker = || {
            WorkerLaunchConfig::new(
                PathBuf::from("unused-native-image-worker"),
                profile_id,
                WorkerId(Uuid::from_u128(0x1977)),
                NATIVE_IMAGE_REGISTRY_VERSION,
                1024,
            )
        };

        let config = NativeExecutionControllerConfig::new(
            fixture_asset_service(&roots)?,
            presentation.clone(),
            worker(),
            true,
        )?;
        assert!(matches!(
            config.with_provider_registry(pin.clone()),
            Err(NativeImageRuntimeError::Registry(message))
                if message.contains("requires a worker registry deployment")
        ));

        let mismatched_deployment = empty_worker_registry_deployment(8, &"a".repeat(64))?;
        let config = NativeExecutionControllerConfig::new(
            fixture_asset_service(&roots)?,
            presentation.clone(),
            worker().with_registry_deployment(mismatched_deployment),
            true,
        )?;
        assert!(matches!(
            config.with_provider_registry(pin.clone()),
            Err(NativeImageRuntimeError::Registry(message))
                if message.contains("differs from the worker registry deployment")
        ));

        let matching_deployment = empty_worker_registry_deployment(7, &"a".repeat(64))?;
        let config = NativeExecutionControllerConfig::new(
            fixture_asset_service(&roots)?,
            presentation,
            worker().with_registry_deployment(matching_deployment),
            true,
        )?
        .with_provider_registry(pin.clone())?;
        assert_eq!(config.provider_registry, Some(pin));
        Ok(())
    }

