    #[test]
    fn ksampler_resolves_profile_before_sd15_schedule_noise_and_prediction()
    -> Result<(), Box<dyn std::error::Error>> {
        for (replacement, prediction) in [
            (
                sim_sampler::SamplingProfileReplacement::DiscreteVPrediction,
                sim_sampler::PredictionInterpretation::VPrediction,
            ),
            (
                sim_sampler::SamplingProfileReplacement::DiscreteX0,
                sim_sampler::PredictionInterpretation::Denoised,
            ),
        ] {
            let base_profile = NativeSamplingPolicy::sd15()?;
            let graph = ExecutionHookGraph::checked(
                17,
                vec![ExecutionHookOperation {
                    identifier: "replace-sd15-with-source-profile".to_owned(),
                    order: 1,
                    kind: ExecutionHookKind::SamplingProfile,
                    scale: 1.0,
                    bias: 0.0,
                    start_percent: 0.0,
                    end_percent: 1.0,
                    rng_address: 41,
                    rng_amplitude: 0.0,
                    hypernetwork: None,
                    context_window: None,
                    sampling_profile: Some(replacement),
                }],
            )?;
            let effective = resolved_ksampler_profile(base_profile.clone(), &graph)?;
            assert_eq!(effective.prediction(), prediction);
            assert_ne!(effective.identity(), base_profile.identity());
            let plan = checked_native_diffusion_plan_for_profile(
                &effective, "euler", "normal", 23, 4, 7.0, 1.0,
            )?;
            assert_eq!(plan.profile(), effective.identity());

            let (backend, workspace_authority) = CpuWorkspaceAuthority::create_backend(1 << 20)?;
            let cancellation = CancellationToken::default();
            let tensor_context = ExecutionContext {
                stream: StreamId::DEFAULT,
                scratch: workspace_authority.authorize_workspace(1 << 20)?,
                rng_phase: None,
                cancellation: &cancellation,
            };
            let sigmas = normal_sigmas_for_profile(&effective, &backend, &tensor_context, 4, 1.0)?;
            let sigma = *sigmas.first().ok_or("replacement schedule is empty")?;
            let latent = tensor_from_f32(&backend, &[1], &[3.0], &tensor_context)?;
            let raw_prediction = tensor_from_f32(&backend, &[1], &[0.5], &tensor_context)?;
            let scaled_input = scale_model_input_for_profile(
                &effective,
                &backend,
                &latent,
                sigma,
                &tensor_context,
            )?;
            let scaled_values = tensor_to_f32(&backend, &scaled_input, &tensor_context)?;
            let expected_input = 3.0 / (sigma * sigma + 1.0).sqrt();
            assert!(
                (scaled_values.first().ok_or("scaled input absent")? - expected_input).abs() < 1e-6
            );

            let replacement_prediction = interpret_prediction_for_profile(
                &effective,
                &backend,
                &raw_prediction,
                &latent,
                sigma,
                &tensor_context,
            )?;
            let base_prediction = interpret_prediction_for_profile(
                &base_profile,
                &backend,
                &raw_prediction,
                &latent,
                sigma,
                &tensor_context,
            )?;
            let replacement_values =
                tensor_to_f32(&backend, &replacement_prediction, &tensor_context)?;
            let base_values = tensor_to_f32(&backend, &base_prediction, &tensor_context)?;
            assert_ne!(&*replacement_values, &*base_values);
            assert_eq!(
                model_time_for_profile(&effective, sigma)?,
                effective.model_time_for_sigma(sigma)?
            );
        }
        Ok(())
    }

