    #[test]
    fn generated_registry_is_comprehensive_and_preserves_union_frontend_types()
    -> Result<(), Box<dyn std::error::Error>> {
        let bindings = generated_family_node_bindings()?;
        let registry = generated_native_node_registry_projection(None)?;
        registry.validate_comprehensive_bindings()?;
        let catalog = NodeRegistry::built_in()?;
        let provider_descriptors = catalog
            .registered()
            .values()
            .filter(|descriptor| descriptor.catalog_status == CatalogNodeStatus::ProviderRequired)
            .collect::<Vec<_>>();
        assert_eq!(provider_descriptors.len(), 224);
        let mut provider_namespaces = BTreeSet::new();
        for descriptor in &provider_descriptors {
            assert_eq!(
                registry.binding_declared_disposition(&descriptor.node_identifier),
                Some(NativeNodeBindingDisposition::ProviderRequired)
            );
            assert_eq!(
                registry.provider_binding_is_activated(&descriptor.node_identifier),
                Some(false)
            );
            assert!(registry.node(&descriptor.node_identifier).is_none());
            let expected_namespace = authoritative_provider_namespace(
                &descriptor.feature_id,
                &descriptor.node_identifier,
            )?;
            assert_eq!(
                registry.binding_implementation_namespace(&descriptor.node_identifier),
                Some(expected_namespace)
            );
            assert_ne!(expected_namespace, "sim-api");
            assert!(!expected_namespace.contains("sim-node-"));
            provider_namespaces.insert(expected_namespace);
        }
        assert_eq!(provider_namespaces.len(), 33);
        let paid = registry
            .descriptor("ElevenLabsAudioIsolation")
            .and_then(|descriptor| descriptor.source_schema.as_ref())
            .and_then(|schema| schema.node.price_badge.as_ref())
            .ok_or("paid provider descriptor lost its source price badge")?;
        paid.validate()?;
        assert_eq!(
            registry.binding_implementation_namespace("ElevenLabsAudioIsolation"),
            Some("zed.sim.provider.elevenlabs")
        );
        for class_type in [
            "LoadImage",
            "ImageScale",
            "ImageInvert",
            "PreviewImage",
            "SaveImage",
        ] {
            assert!(registry.descriptor(class_type).is_some());
            assert!(registry.node(class_type).is_some());
        }
        for binding in &bindings {
            let class_type = &binding.descriptor().class_type;
            assert_eq!(
                registry.binding_declared_disposition(class_type),
                Some(binding.disposition())
            );
            assert!(
                registry
                    .binding_source(class_type)
                    .is_some_and(|source| !source.is_empty())
            );
            assert!(registry.presentation(class_type).is_some());
        }

        let cpu_backend = projection_only_cpu_backend()?;
        let executor = NativeImageExecutor::new_with_generated_registry(
            ProfileId(Uuid::new_v4()),
            BTreeMap::new(),
            true,
            cpu_backend,
        )?;
        executor.nodes.validate_comprehensive_bindings()?;
        let fixture_count = if cfg!(feature = "test-support") { 8 } else { 0 };
        assert_eq!(
            executor.nodes.descriptor_len(),
            registry.descriptor_len() + fixture_count
        );
        assert_eq!(
            executor.nodes.node_len(),
            registry.node_len() + fixture_count
        );

        let frontend = generated_native_frontend_descriptors(None)?;
        assert_eq!(frontend.len(), registry.descriptor_len());
        let contracts = generated_native_frontend_contracts(None)?;
        assert_eq!(contracts.len(), registry.descriptor_len());
        for (class_type, contract) in &contracts {
            contract.runtime.validate_exact_schema_v2()?;
            assert_eq!(contract.graph.type_name, *class_type);
            assert_eq!(
                contract.runtime.source_schema.as_ref().map(|schema| schema
                    .inputs
                    .iter()
                    .map(|input| &input.name)
                    .collect::<Vec<_>>()),
                Some(
                    contract
                        .graph
                        .inputs
                        .iter()
                        .map(|input| &input.name)
                        .collect::<Vec<_>>()
                )
            );
            assert_eq!(
                contract.presentation,
                registry
                    .presentation(class_type)
                    .ok_or("frontend presentation is absent from the registry")?
                    .clone()
            );
            assert_eq!(
                Some(contract.disposition),
                registry.binding_disposition(class_type)
            );
        }
        if let Some((class_type, descriptor, input)) =
            registry.descriptors().find_map(|(class_type, descriptor)| {
                descriptor
                    .inputs
                    .iter()
                    .find(|input| input.accepted_types.members().len() > 1)
                    .map(|input| (class_type, descriptor, input))
            })
        {
            let frontend_descriptor = frontend
                .get(class_type)
                .ok_or("union descriptor was absent from frontend projection")?;
            let frontend_input = frontend_descriptor
                .inputs
                .iter()
                .find(|candidate| candidate.name == input.name)
                .ok_or("union input was absent from frontend projection")?;
            assert!(frontend_input.type_name.contains('|'));
            assert_eq!(frontend_descriptor.outputs.len(), descriptor.outputs.len());
        }
        Ok(())
    }

    #[test]
    fn generated_diffusion_registry_preserves_explicit_provider_and_defaults_to_resource_service()
    -> Result<(), Box<dyn std::error::Error>> {
        let cache_identity_calls = Arc::new(AtomicUsize::new(0));
        let registry = generated_native_node_registry_projection(Some(Arc::new(
            WorkspaceProbeDiffusionProvider {
                observed: Arc::new(AtomicBool::new(false)),
                cache_identity_calls: cache_identity_calls.clone(),
            },
        )))?;
        registry.validate_comprehensive_bindings()?;
        let descriptor = registry
            .descriptor("CheckpointLoaderSimple")
            .ok_or("generated diffusion registry omitted CheckpointLoaderSimple")?;
        assert_eq!(descriptor.effect, EffectClass::ReadsArtifact);
        assert_eq!(descriptor.cache, RuntimeCachePolicy::InputIdentity);
        let registry_construction_calls = cache_identity_calls.load(Ordering::SeqCst);
        let node = registry
            .node("CheckpointLoaderSimple")
            .ok_or("generated diffusion registry omitted checkpoint implementation")?;
        let (backend, workspace_authority) = CpuWorkspaceAuthority::create_backend(1 << 20)?;
        let attempt_id = AttemptId(Uuid::from_u128(0x402_301));
        let generation = crate::NativeHandleStoreGeneration::new()?;
        let context = NodeContext::new(
            PromptId(Uuid::from_u128(0x402_302)),
            attempt_id,
            NodeId("checkpoint-loader".to_owned()),
            CancellationToken::default(),
            workspace_authority.authorize_workspace(1 << 20)?,
            generation.handle_store_for_attempt(attempt_id),
        )?;
        let inputs = BTreeMap::from([(
            "ckpt_name".to_owned(),
            native(json!("checkpoint.safetensors")),
        )]);
        let dependencies = node.cache_dependencies(&context, &inputs)?;
        assert_eq!(
            dependencies.artifact_digests.get("clip.execution"),
            Some(&"5".repeat(64))
        );
        assert_eq!(
            cache_identity_calls.load(Ordering::SeqCst),
            registry_construction_calls + 1
        );
        let default_registry = generated_native_node_registry_projection(None)?;
        let default_node = default_registry
            .node("CheckpointLoaderSimple")
            .ok_or("default loader missing")?;
        let error = default_node
            .cache_dependencies(&context, &inputs)
            .expect_err("default loader must require the canonical model resource service");
        assert_eq!(error.code, "native_model_resource_unavailable");
        assert_eq!(
            cache_identity_calls.load(Ordering::SeqCst),
            registry_construction_calls + 1
        );
        drop(backend);
        Ok(())
    }

    #[test]
    fn native_model_resource_execution_applies_controller_handle_store_identity()
    -> Result<(), Box<dyn std::error::Error>> {
        let (backend, _) = CpuWorkspaceAuthority::create_backend(1 << 20)?;
        let executor = NativeImageExecutor::new_with_generated_registry(
            ProfileId(Uuid::from_u128(0x402_331)),
            BTreeMap::new(),
            true,
            Arc::new(backend),
        )?;
        let controller_generation = crate::NativeHandleStoreGeneration::new()?;
        let original_identity = controller_generation.identity();
        let binding = NativeModelSourceWorkerBinding::checked(Uuid::from_u128(0x402_332), 1, 1, 1)?
            .with_handle_store_identity(original_identity)?;
        let (first, _first_host) = executor.clone().with_model_source_worker(binding.clone())?;
        let attempt_id = AttemptId(Uuid::from_u128(0x402_333));
        let cancellation = CancellationToken::default();
        let first_store = first
            .handle_store_generation
            .lock()
            .clone()
            .handle_store_for_attempt(attempt_id);
        let old_handle = first_store.publish(
            NativeStoredPayload::Artifact(Arc::new(NativeArtifactPayload::checked(
                NativeArtifactKind::Svg,
                "image/svg+xml".to_owned(),
                b"<svg/>".to_vec(),
            )?)),
            &cancellation,
        )?;

        let (same_generation, _same_host) = executor.clone().with_model_source_worker(binding)?;
        let same_store = same_generation
            .handle_store_generation
            .lock()
            .clone()
            .handle_store_for_attempt(attempt_id);
        assert_eq!(same_store.identity(), original_identity);
        drop(same_store.resolve(&old_handle, old_handle.handle_type(), &cancellation)?);

        let replacement_identity = controller_generation.fresh_generation()?.identity();
        let replacement_binding =
            NativeModelSourceWorkerBinding::checked(Uuid::from_u128(0x402_332), 2, 2, 1)?
                .with_handle_store_identity(replacement_identity)?;
        let (replacement, _replacement_host) =
            executor.with_model_source_worker(replacement_binding)?;
        let replacement_store = replacement
            .handle_store_generation
            .lock()
            .clone()
            .handle_store_for_attempt(attempt_id);
        assert_eq!(replacement_identity.store_id, original_identity.store_id);
        assert_ne!(
            replacement_identity.generation_id,
            original_identity.generation_id
        );
        assert!(matches!(
            replacement_store.resolve(&old_handle, old_handle.handle_type(), &cancellation,),
            Err(NativeHandleStoreError::WrongGeneration)
        ));
        first_store.revoke(&old_handle, &cancellation)?;
        Ok(())
    }

